/* ELTAUM_MOBILE_PREMIUM_FILTERS_CARDS_20260606_v68 */
:root{
  --ds-bg-base:#07080f;--ds-bg-surface:#0d0f1c;--ds-bg-raised:#111526;
  --ds-brand:#c8973a;--ds-brand-light:#e8bb6a;--ds-brand-dim:rgba(200,151,58,.12);
  --ds-border:rgba(180,189,211,.16);--ds-border-brand:rgba(200,151,58,.35);
  --ds-radius-lg:14px;--ds-radius-md:10px;--ds-radius-sm:6px;
  --ds-ease:cubic-bezier(.4,0,.2,1);--ds-duration-normal:200ms;
}
/* Catálogo de Fundos CAIXA — Elton Cardoso Teotonio
   style.css — extraído do index.html (v20) */

:root{
  --bg:#07080f;--bg2:#0c0e1a;--bg3:#111526;--bg4:#181d36;
  --gold:#c8973a;--gold2:#e8bb6a;--gold3:#f5d48a;
  --gold-dim:rgba(200,151,58,.1);--gold-glow:rgba(200,151,58,.2);
  --text:#edf1fb;--muted:#a6b0c9;--muted2:#7f8aa8;
  --green:#2ed17a;--green-dim:rgba(46,209,122,.1);
  --red:#f05565;--red-dim:rgba(240,85,101,.1);
  --blue:#5b9cf6;--blue-dim:rgba(91,156,246,.1);
  --orange:#fb923c;--purple:#a78bfa;
  --border:rgba(200,151,58,.22);--border2:rgba(255,255,255,.085);--border3:rgba(255,255,255,.13);
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Inter',sans-serif;background:var(--bg);color:var(--text);min-height:100vh;overflow-x:hidden;-webkit-font-smoothing:antialiased}
body::before{content:'';position:fixed;inset:0;z-index:0;pointer-events:none;
  background:radial-gradient(ellipse 80% 50% at 10% -5%,rgba(200,151,58,.055) 0%,transparent 55%),
             radial-gradient(ellipse 60% 60% at 90% 105%,rgba(91,156,246,.04) 0%,transparent 55%)}
body::after{content:'';position:fixed;inset:0;z-index:0;pointer-events:none;
  background-image:linear-gradient(rgba(200,151,58,.018) 1px,transparent 1px),
                   linear-gradient(90deg,rgba(200,151,58,.018) 1px,transparent 1px);
  background-size:72px 72px}
.page{position:relative;z-index:1;max-width:1760px;margin:0 auto;padding:32px 28px 100px}

/* ── HEADER ── */
header{display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:20px;
  padding-bottom:28px;border-bottom:1px solid var(--border);margin-bottom:0}
.brand{display:flex;align-items:center;gap:16px}
.brand-logo{width:48px;height:48px;border-radius:12px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg,var(--gold) 0%,var(--gold2) 100%);
  box-shadow:0 0 32px var(--gold-glow);
  font-family:'Cormorant Garamond',serif;font-size:1.55rem;font-weight:700;color:#07080f}
.brand-text h1{font-family:'Cormorant Garamond',serif;font-size:clamp(1.3rem,2.5vw,1.85rem);font-weight:700;
  color:var(--gold2);letter-spacing:.015em;line-height:1.1}
.brand-text p{font-size:.68rem;color:var(--muted);margin-top:4px;letter-spacing:.08em;text-transform:uppercase;font-weight:400}
.live-badge{display:inline-flex;align-items:center;gap:8px;padding:8px 16px;border-radius:20px;
  background:var(--bg3);border:1px solid var(--border);font-size:.7rem;color:var(--muted);
  font-family:'JetBrains Mono',monospace;white-space:nowrap}
.live-dot{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 8px var(--green);flex-shrink:0;animation:pulse 2.4s infinite}
@keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.35;transform:scale(.75)}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes fadeUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
@keyframes slideDown{from{opacity:0;max-height:0}to{opacity:1;max-height:500px}}

/* ── AVISOS ── */
.top-disclaimer{
  margin-top:18px;
  display:flex;
  gap:12px;
  align-items:flex-start;
  padding:14px 18px;
  border:1px solid rgba(200,151,58,.18);
  border-radius:14px;
  background:linear-gradient(180deg,rgba(200,151,58,.09),rgba(255,255,255,.018));
  color:#b8c0d6;
  font-size:.74rem;
  line-height:1.6;
  box-shadow:0 8px 28px rgba(0,0,0,.18);
}
.top-disclaimer-icon{
  flex-shrink:0;
  width:24px;
  height:24px;
  border-radius:8px;
  display:flex;
  align-items:center;
  justify-content:center;
  background:var(--gold-dim);
  border:1px solid rgba(200,151,58,.18);
  color:var(--gold2);
  font-size:.78rem;
}
.top-disclaimer strong{color:var(--gold2);font-weight:700}
.top-disclaimer span{color:var(--text)}

/* ── KPI GRID ── */
.section-gap{margin-top:28px}
.kpi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}
.kpi{background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:20px 18px;
  position:relative;overflow:hidden;cursor:default;transition:transform .2s,border-color .2s,box-shadow .2s}
.kpi:hover{transform:translateY(-3px);border-color:rgba(200,151,58,.3);box-shadow:0 10px 40px rgba(0,0,0,.35)}
.kpi::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;
  background:linear-gradient(90deg,var(--gold) 0%,transparent 75%)}
.kpi-icon{font-size:.95rem;margin-bottom:8px;opacity:.8}
.kpi-label{font-size:.62rem;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);font-weight:600;margin-bottom:7px}
.kpi-value{font-family:'Cormorant Garamond',serif;font-size:1.85rem;font-weight:700;color:var(--gold2);line-height:1}
.kpi-value.pos{color:var(--green);font-size:1.5rem}.kpi-value.neg{color:var(--red);font-size:1.5rem}
.kpi-sub{font-size:.65rem;color:var(--muted);margin-top:6px;line-height:1.4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* ── SEÇÃO MERCADO ── */
.section-title{display:flex;align-items:center;gap:10px;margin-bottom:14px}
.section-title h2{font-family:'Cormorant Garamond',serif;font-size:1.1rem;font-weight:700;color:var(--gold2);letter-spacing:.03em}
.section-badge{font-size:.6rem;padding:3px 9px;border-radius:6px;border:1px solid var(--border2);
  color:var(--muted);font-family:'JetBrains Mono',monospace;display:flex;align-items:center;gap:5px}
.badge-dot{width:5px;height:5px;border-radius:50%}
.badge-dot.green{background:var(--green);box-shadow:0 0 5px var(--green)}
.badge-dot.blue{background:var(--blue);box-shadow:0 0 5px var(--blue)}

/* ── CARDS DE REFERÊNCIA (Selic+CDI unificado + Poupança) ── */
.indic-ref-bar{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:14px}

/* Card Selic+CDI unificado */
.indic-ref-card{background:var(--bg2);border:1px solid var(--border);border-radius:12px;
  padding:18px 22px;display:flex;gap:20px;flex:1;min-width:240px;
  position:relative;overflow:hidden;transition:border-color .2s}
.indic-ref-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px}
.indic-ref-card.selic-cdi::before{background:linear-gradient(90deg,var(--gold),var(--green) 60%,transparent)}
.indic-ref-card.poup::before{background:linear-gradient(90deg,var(--blue),transparent)}

.selic-cdi-block{display:flex;flex-direction:column;gap:2px;flex:1}
.selic-cdi-divider{width:1px;background:var(--border2);margin:4px 0;flex-shrink:0}
.indic-ref-label{font-size:.58rem;text-transform:uppercase;letter-spacing:.1em;color:var(--muted2);font-weight:600;margin-bottom:3px}
.indic-ref-val{font-family:'Cormorant Garamond',serif;font-size:1.9rem;font-weight:700;line-height:1}
.indic-ref-val.gold{color:var(--gold2)}
.indic-ref-val.green{color:var(--green)}
.indic-ref-val.blue{color:var(--blue)}
.indic-ref-sub{font-size:.6rem;color:var(--muted);font-family:'JetBrains Mono',monospace;margin-top:3px}
.selic-change-badge{display:inline-flex;align-items:center;gap:5px;margin-top:4px;
  font-size:.58rem;color:var(--muted);font-family:'JetBrains Mono',monospace}
.selic-change-date{color:var(--gold)}
.copom-link{display:inline-flex;align-items:center;gap:4px;margin-top:6px;
  font-size:.6rem;color:var(--gold);text-decoration:none;font-family:'JetBrains Mono',monospace;
  padding:3px 8px;border:1px solid var(--border);border-radius:6px;background:var(--gold-dim);
  transition:all .15s;white-space:nowrap}
.copom-link:hover{background:rgba(200,151,58,.2);border-color:var(--gold2);color:var(--gold2)}
.cdi-rel{font-size:.58rem;color:var(--muted2);margin-top:5px;font-style:italic;font-family:'JetBrains Mono',monospace}

/* Card Poupança */
.poup-header{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;width:100%}
.poup-values{display:flex;gap:18px;margin-top:8px}
.poup-rule{display:flex;flex-direction:column;gap:2px}
.poup-rule-label{font-size:.58rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted2);font-weight:600}
.poup-rule-val{font-family:'Cormorant Garamond',serif;font-size:1.5rem;font-weight:700;line-height:1}
.poup-rule-val.blue{color:var(--blue)}
.poup-rule-val.muted{color:var(--muted)}
.poup-rule-sub{font-size:.58rem;color:var(--muted2);font-family:'JetBrains Mono',monospace}
.poup-expand-btn{background:transparent;border:1px solid var(--border2);border-radius:8px;color:var(--muted);
  font-size:.65rem;padding:4px 10px;cursor:pointer;transition:all .15s;white-space:nowrap;flex-shrink:0}
.poup-expand-btn:hover{border-color:var(--blue);color:var(--blue);background:var(--blue-dim)}
.poup-explain{overflow:hidden;max-height:0;transition:max-height .35s ease,opacity .25s;opacity:0;width:100%}
.poup-explain.open{max-height:300px;opacity:1}
.poup-explain-inner{padding:14px 0 4px;border-top:1px solid var(--border2);margin-top:10px}
.poup-explain-title{font-size:.65rem;font-weight:700;color:var(--gold2);margin-bottom:6px;text-transform:uppercase;letter-spacing:.06em}
.poup-explain-row{display:flex;gap:10px;margin-bottom:6px;align-items:flex-start}
.poup-explain-tag{font-size:.58rem;padding:2px 7px;border-radius:5px;font-weight:700;white-space:nowrap;flex-shrink:0;margin-top:1px}
.tag-nova{background:var(--blue-dim);color:var(--blue);border:1px solid rgba(91,156,246,.2)}
.tag-antiga{background:rgba(200,151,58,.1);color:var(--gold);border:1px solid rgba(200,151,58,.2)}
.poup-explain-text{font-size:.65rem;color:var(--muted);line-height:1.5}
.poup-bcb-link{display:inline-flex;align-items:center;gap:4px;margin-top:8px;
  font-size:.6rem;color:var(--blue);text-decoration:none;font-family:'JetBrains Mono',monospace;
  padding:3px 8px;border:1px solid rgba(91,156,246,.2);border-radius:6px;background:var(--blue-dim);transition:all .15s}
.poup-bcb-link:hover{background:rgba(91,156,246,.18);color:#8bbfff}

/* ── TABELA DE INDICADORES COM TABS ── */
.indic-tabs-bar{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:10px}
.indic-tabs-label{font-size:.62rem;color:var(--muted);font-family:'JetBrains Mono',monospace}
.indic-tabs{display:flex;gap:4px}
.indic-tab{padding:5px 14px;border-radius:8px;border:1px solid var(--border2);background:transparent;
  color:var(--muted);font-size:.7rem;font-family:'Inter',sans-serif;font-weight:500;cursor:pointer;transition:all .15s}
.indic-tab:hover{border-color:var(--gold);color:var(--gold)}
.indic-tab.active{background:var(--gold-dim);border-color:var(--gold);color:var(--gold2);font-weight:600}

.indic-table-wrap{border:1px solid var(--border);border-radius:14px;overflow:hidden;background:var(--bg2)}
.indic-table{width:100%;border-collapse:collapse}
.indic-table thead tr{background:linear-gradient(90deg,var(--bg4),var(--bg3));border-bottom:1px solid var(--border)}
.indic-table th{padding:11px 16px;font-size:.6rem;text-transform:uppercase;letter-spacing:.1em;color:var(--gold);
  font-weight:600;text-align:right;white-space:nowrap}
.indic-table th:first-child{text-align:left;min-width:200px}
.indic-table th.th-ref{color:var(--muted2);text-align:center}
.indic-table th.th-acum{color:var(--gold2)}
.indic-table tbody tr{border-bottom:1px solid var(--border2);transition:background .12s}
.indic-table tbody tr:last-child{border-bottom:none}
.indic-table tbody tr:hover{background:rgba(200,151,58,.03)}
.indic-table td{padding:13px 16px;text-align:right;vertical-align:middle}
.indic-table td:first-child{text-align:left}
.indic-table td.td-ref{text-align:center}
.indic-name{display:flex;align-items:center;gap:8px}
.indic-icon{font-size:.95rem}
.indic-title{font-family:'Inter',sans-serif;font-size:.82rem;font-weight:600;color:var(--text)}
.indic-subtitle{font-size:.6rem;color:var(--muted2);margin-top:1px;font-family:'JetBrains Mono',monospace}
.indic-val{font-family:'Cormorant Garamond',serif;font-size:1.2rem;font-weight:700;color:var(--text);line-height:1}
.indic-val-sub{font-size:.6rem;color:var(--muted);margin-top:2px;font-family:'JetBrains Mono',monospace}
.indic-pct{font-family:'JetBrains Mono',monospace;font-size:.82rem;font-weight:600}
.indic-pct.pos{color:var(--green)}.indic-pct.neg{color:var(--red)}.indic-pct.zero,.indic-pct.dash{color:var(--muted2)}
.indic-pct-label{font-size:.58rem;color:var(--muted2);margin-top:2px;font-family:'JetBrains Mono',monospace}
.ref-badge{display:inline-block;padding:3px 8px;border-radius:6px;background:var(--bg3);
  border:1px solid var(--border2);font-size:.65rem;font-family:'JetBrains Mono',monospace;color:var(--muted)}
.indic-footnote{padding:10px 16px;font-size:.64rem;color:#8a95b2;border-top:1px solid var(--border2);
  font-family:'JetBrains Mono',monospace;font-style:italic}
.indic-row-group{background:rgba(200,151,58,.015)}

/* ── SEÇÃO DÓLAR ── */
.dolar-grid{display:grid;grid-template-columns:300px minmax(0,1fr);gap:14px;align-items:start;width:100%;max-width:100%;overflow:hidden}
@media(max-width:900px){.dolar-grid{grid-template-columns:1fr}}

/* Card do dia */
.dolar-day-card{background:var(--bg2);border:1px solid var(--border);border-radius:14px;overflow:hidden;
  transition:border-color .2s,box-shadow .2s}
.dolar-day-card:hover{border-color:rgba(200,151,58,.25);box-shadow:0 6px 30px rgba(0,0,0,.3)}
.dolar-day-card::before{content:'';display:block;height:2px;background:linear-gradient(90deg,var(--gold),var(--green) 60%,transparent)}
.dolar-day-header{padding:14px 18px 10px;border-bottom:1px solid var(--border2)}
.dolar-day-title{font-family:'Cormorant Garamond',serif;font-size:.95rem;font-weight:700;color:var(--gold2)}
.dolar-day-sub{font-size:.72rem;color:#b8c0d6;font-family:'JetBrains Mono',monospace;margin-top:3px}
.dolar-day-body{padding:18px}
.dolar-day-rate{font-family:'Cormorant Garamond',serif;font-size:2.8rem;font-weight:700;color:var(--gold2);line-height:1;margin-bottom:4px}
.dolar-day-ref{font-size:.62rem;color:var(--muted);font-family:'JetBrains Mono',monospace;margin-bottom:12px}
.dolar-day-metrics{display:flex;flex-direction:column;gap:8px}
.dolar-metric{display:flex;align-items:center;justify-content:space-between;padding:7px 10px;
  background:var(--bg3);border-radius:8px;border:1px solid var(--border2)}
.dolar-metric-label{font-size:.62rem;color:var(--muted2);font-family:'JetBrains Mono',monospace}
.dolar-metric-val{font-family:'JetBrains Mono',monospace;font-size:.78rem;font-weight:600}
.dolar-metric-val.pos{color:var(--green)}.dolar-metric-val.neg{color:var(--red)}.dolar-metric-val.muted{color:var(--muted)}
.dolar-resumo-metrics .dolar-metric{padding:9px 10px}
.dolar-resumo-metrics .dolar-metric-label{max-width:130px;line-height:1.25}
.dolar-resumo-metrics .dolar-metric-val{font-size:.82rem}
.dolar-spread{display:flex;gap:6px;margin-top:2px}
.dolar-spread-item{flex:1;background:var(--bg3);border-radius:7px;padding:6px 8px;border:1px solid var(--border2);text-align:center}
.dolar-spread-label{font-size:.55rem;color:var(--muted2);text-transform:uppercase;letter-spacing:.08em;margin-bottom:2px}
.dolar-spread-val{font-family:'Cormorant Garamond',serif;font-size:1.1rem;font-weight:700;color:var(--text)}

.dolar-ptax-compact{
  display:inline-flex;
  align-items:center;
  gap:6px;
  margin:2px 0 12px;
  padding:6px 10px;
  border-radius:8px;
  border:1px solid rgba(200,151,58,.18);
  background:rgba(200,151,58,.06);
  color:#b6bfd5;
  font-size:.62rem;
  font-family:'JetBrains Mono',monospace;
}

/* Timeline mensal */
.dolar-right{display:flex;flex-direction:column;gap:14px;min-width:0;width:100%;max-width:100%;overflow:hidden}
.dolar-timeline-card{background:var(--bg2);border:1px solid var(--border);border-radius:14px;overflow:hidden;width:100%;max-width:100%;min-width:0}
.dolar-timeline-card::before{content:'';display:block;height:2px;background:linear-gradient(90deg,var(--gold),transparent 70%)}
.dolar-timeline-header{padding:12px 18px;border-bottom:1px solid var(--border2);
  display:flex;align-items:center;justify-content:space-between;gap:10px;user-select:none;transition:background .15s}
.dolar-timeline-header:hover{background:rgba(200,151,58,.03)}
.dolar-timeline-title-wrap{display:flex;flex-direction:column;gap:2px;min-width:0}
.dolar-timeline-title{font-family:'Cormorant Garamond',serif;font-size:.95rem;font-weight:700;color:var(--gold2)}
.dolar-timeline-sub{font-size:.62rem;color:#9aa6c3;font-family:'JetBrains Mono',monospace}
.dolar-timeline-toggle{display:inline-flex;align-items:center;gap:5px;border:1px solid var(--border2);background:var(--bg3);
  color:var(--muted);border-radius:8px;padding:5px 10px;font-size:.62rem;font-family:'Inter',sans-serif;cursor:pointer;transition:all .15s;white-space:nowrap}
.dolar-timeline-toggle:hover{border-color:var(--gold);color:var(--gold2);background:var(--gold-dim)}
.dolar-timeline-body{overflow:hidden;max-height:0;transition:max-height .35s ease}
.dolar-timeline-body.open{max-height:560px}
.dolar-months{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(92px,1fr));
  gap:8px;
  overflow-x:visible;
  padding:12px 16px 16px;
}
.dolar-month-item{
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:4px;
  min-width:0;
  padding:10px 8px;
  border-radius:10px;
  border:1px solid var(--border2);
  background:var(--bg3);
  transition:border-color .15s,background .15s,transform .15s;
  cursor:default;
}
.dolar-month-item:hover{border-color:var(--gold);background:var(--gold-dim);transform:translateY(-2px)}
.dolar-month-item.current{border-color:var(--gold);background:var(--gold-dim)}
.dolar-month-label{font-size:.58rem;color:var(--muted2);font-family:'JetBrains Mono',monospace;text-transform:uppercase}
.dolar-month-val{font-family:'Cormorant Garamond',serif;font-size:1.08rem;font-weight:700;color:var(--gold2)}
.dolar-month-var{font-size:.72rem;font-family:'JetBrains Mono',monospace;font-weight:700}
.dolar-month-var.pos{color:#4de896}.dolar-month-var.neg{color:#ff6b7a}.dolar-month-var.zero{color:var(--muted)}
.dolar-source-note{
  display:flex;
  align-items:center;
  gap:8px;
  margin:0 16px 14px;
  padding:9px 12px;
  border-radius:10px;
  border:1px solid rgba(200,151,58,.14);
  background:rgba(200,151,58,.055);
  color:#aeb7cf;
  font-size:.64rem;
  font-family:'Inter',sans-serif;
  line-height:1.45;
}
.dolar-source-note .source-label,
.dolar-chart-source .source-label{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  flex-shrink:0;
  padding:2px 7px;
  border-radius:6px;
  border:1px solid rgba(200,151,58,.24);
  background:rgba(200,151,58,.11);
  color:var(--gold2);
  font-size:.56rem;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:.08em;
}
.dolar-source-note a{color:var(--gold2);text-decoration:none}.dolar-source-note a:hover{text-decoration:underline}

/* Gráfico dólar */
.dolar-chart-card{background:var(--bg2);border:1px solid var(--border);border-radius:14px;overflow:hidden;
  transition:border-color .2s,box-shadow .2s;width:100%;max-width:100%;min-width:0}
.dolar-chart-card:hover{border-color:rgba(200,151,58,.25);box-shadow:0 6px 30px rgba(0,0,0,.3)}
.dolar-chart-card::before{content:'';display:block;height:2px;background:linear-gradient(90deg,var(--gold),transparent 70%)}
.dolar-chart-header{padding:14px 18px 10px;border-bottom:1px solid var(--border2);display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;min-width:0}
.dolar-chart-title{font-family:'Cormorant Garamond',serif;font-size:1rem;font-weight:700;color:var(--gold2)}
.dolar-chart-sub{font-size:.6rem;color:var(--muted);font-family:'JetBrains Mono',monospace}
.dolar-chart-body{padding:18px 20px;position:relative;height:clamp(260px,28vw,340px);min-height:260px;max-height:340px;width:100%;max-width:100%;overflow:hidden}
.dolar-chart-body canvas{width:100% !important;height:100% !important;display:block}
.dolar-chart-source{
