.dolar-source-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:8px}
.dolar-source-link{display:inline-flex;align-items:center;gap:5px;padding:5px 10px;border-radius:8px;border:1px solid rgba(200,151,58,.28);background:rgba(200,151,58,.08);color:var(--gold2);font-family:'Inter',sans-serif;font-size:.68rem;font-weight:600;text-decoration:none;transition:all .15s}
.dolar-source-link:hover{border-color:var(--gold2);background:rgba(200,151,58,.16);color:var(--gold3);text-decoration:none}

/* ── FOCUS ── */
.focus-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:10px}
.fcad{background:var(--bg2);border:1px solid var(--border2);border-radius:12px;padding:16px 18px;
  position:relative;overflow:hidden;transition:border-color .2s,transform .2s;cursor:default}
.fcad:hover{border-color:rgba(91,156,246,.3);transform:translateY(-2px)}
.fcad::before{content:'';position:absolute;top:0;left:0;right:0;height:1.5px;
  background:linear-gradient(90deg,var(--blue) 0%,transparent 70%);opacity:.6}
.fcad-label{font-size:.6rem;text-transform:uppercase;letter-spacing:.1em;color:var(--muted2);font-weight:600;margin-bottom:2px}
.fcad-sub{font-size:.65rem;color:var(--muted);margin-bottom:12px;line-height:1.3}
.fcad-rows{display:flex;flex-direction:column;gap:7px}
.fcad-row{display:flex;align-items:baseline;justify-content:space-between;gap:6px}
.fcad-year{font-size:.6rem;color:var(--muted2);font-family:'JetBrains Mono',monospace;min-width:30px}
.fcad-val{font-family:'Cormorant Garamond',serif;font-size:1.25rem;font-weight:700;color:var(--text);line-height:1}
.fcad-val.hl{color:var(--gold2)}
.fcad-hr{border:none;border-top:1px solid var(--border2);margin:4px 0}
.focus-section-title{
  align-items:flex-start;
  justify-content:flex-start;
  margin-bottom:14px;
}
.focus-title-block{
  display:flex;
  flex-direction:column;
  gap:8px;
  min-width:0;
}
.focus-title-line{
  display:flex;
  align-items:center;
  gap:10px;
  flex-wrap:wrap;
}
.focus-ref{
  display:inline-flex;
  align-items:center;
  gap:10px;
  flex-wrap:wrap;
  width:max-content;
  max-width:100%;
  padding:7px 10px;
  border:1px solid rgba(91,156,246,.22);
  border-radius:10px;
  background:rgba(91,156,246,.075);
  color:#c6cee2;
  font-size:.68rem;
  line-height:1.35;
  font-family:'Inter',sans-serif;
  font-weight:500;
}
.focus-ref strong{
  color:var(--text);
  font-weight:700;
}
.focus-ref-label{
  display:inline-flex;
  align-items:center;
  gap:4px;
  white-space:nowrap;
}
.focus-pdf-link{
  display:inline-flex;
  align-items:center;
  gap:5px;
  padding:4px 9px;
  border-radius:8px;
  border:1px solid rgba(200,151,58,.32);
  background:rgba(200,151,58,.10);
  color:var(--gold2);
  text-decoration:none;
  font-size:.66rem;
  font-weight:700;
  transition:all .15s;
  white-space:nowrap;
}
.focus-pdf-link:hover{
  border-color:var(--gold2);
  background:rgba(200,151,58,.18);
  color:var(--gold3);
}

.focus-explain-card{
  margin:12px 0 16px;
  border:1px solid rgba(91,156,246,.24);
  border-radius:14px;
  background:linear-gradient(180deg,rgba(91,156,246,.075),rgba(255,255,255,.018));
  overflow:hidden;
  box-shadow:0 8px 28px rgba(0,0,0,.18);
}
.focus-explain-header{
  width:100%;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  padding:13px 16px;
  background:rgba(255,255,255,.012);
  border:0;
  border-bottom:1px solid rgba(255,255,255,.055);
  color:var(--text);
  cursor:pointer;
  font-family:'Inter',sans-serif;
  font-size:.84rem;
  font-weight:700;
  text-align:left;
}
.focus-explain-header span:first-child{
  color:var(--gold2);
  display:flex;
  align-items:center;
  gap:6px;
}
.focus-explain-header span:last-child{
  color:#bec7dc;
  font-size:.70rem;
  font-weight:600;
  white-space:nowrap;
}
.focus-explain-body{
  max-height:0;
  overflow:hidden;
  opacity:0;
  transition:max-height .32s ease,opacity .25s ease,padding .25s ease;
  padding:0 16px;
}
.focus-explain-body.open{
  max-height:520px;
  opacity:1;
  padding:14px 16px 16px;
}
.focus-explain-content{
  max-width:1180px;
}
.focus-explain-grid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:12px;
}
.focus-explain-item{
  padding:13px 14px;
  border:1px solid rgba(255,255,255,.07);
  border-radius:12px;
  background:rgba(12,14,26,.56);
}
.focus-explain-kicker{
  display:block;
  margin-bottom:6px;
  color:var(--gold2);
  font-size:.66rem;
  font-weight:700;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.focus-explain-item p{
  color:#cbd3e6;
  font-size:.77rem;
  line-height:1.68;
  margin:0;
  max-width:64ch;
}
.focus-explain-note{
  display:flex;
  align-items:flex-start;
  gap:9px;
  margin-top:12px;
  padding:12px 14px;
  border:1px solid rgba(200,151,58,.22);
  border-radius:12px;
  background:rgba(200,151,58,.075);
  color:#e8d3a5;
  font-size:.73rem;
  line-height:1.6;
}
.focus-explain-note strong{
  color:var(--gold3);
  font-weight:700;
}
.focus-explain-body strong{
  color:var(--text);
  font-weight:700;
}
@media(max-width:900px){
  .focus-explain-grid{grid-template-columns:1fr}
  .focus-explain-body.open{max-height:720px}
}

/* ── CHARTS ── */
.charts-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px}
.chart-card{background:var(--bg2);border:1px solid var(--border);border-radius:14px;overflow:hidden;
  transition:border-color .2s,box-shadow .2s}
.chart-card:hover{border-color:rgba(200,151,58,.25);box-shadow:0 6px 30px rgba(0,0,0,.3)}
.chart-card::before{content:'';display:block;height:2px;background:linear-gradient(90deg,var(--gold),transparent 70%)}
.chart-card-header{padding:14px 18px 10px;border-bottom:1px solid var(--border2);display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px}
.chart-card-title{font-family:'Cormorant Garamond',serif;font-size:1rem;font-weight:700;color:var(--gold2)}
.chart-card-sub{font-size:.6rem;color:var(--muted);font-family:'JetBrains Mono',monospace}
.chart-body{padding:16px 18px;position:relative;height:220px}
.chart-tabs{display:flex;gap:4px}
.chart-tab{padding:3px 10px;border-radius:10px;border:1px solid var(--border2);background:transparent;
  color:var(--muted);font-size:.62rem;font-family:'Inter',sans-serif;cursor:pointer;transition:all .15s}
.chart-tab:hover{border-color:var(--gold);color:var(--gold)}
.chart-tab.active{background:var(--gold-dim);border-color:var(--gold);color:var(--gold2)}

/* ── RANKINGS ── */
.ranking-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}
.rank-card{background:var(--bg2);border:1px solid var(--border);border-radius:14px;overflow:hidden;
  transition:border-color .2s,box-shadow .2s}
.rank-card:hover{border-color:rgba(200,151,58,.25);box-shadow:0 6px 30px rgba(0,0,0,.3)}
.rank-card::before{content:'';display:block;height:2px;background:linear-gradient(90deg,var(--gold),transparent 70%)}
.rank-card-header{padding:14px 18px 10px;border-bottom:1px solid var(--border2);display:flex;align-items:center;gap:8px}
.rank-card-title{font-family:'Cormorant Garamond',serif;font-size:1rem;font-weight:700;color:var(--gold2)}
.rank-list{padding:4px 0}
.rank-item{display:flex;align-items:center;gap:10px;padding:8px 18px;border-bottom:1px solid var(--border2);
  transition:background .12s;cursor:default}
.rank-item:last-child{border-bottom:none}
.rank-item:hover{background:rgba(200,151,58,.03)}
.rank-pos{font-family:'JetBrains Mono',monospace;font-size:.65rem;color:var(--muted2);min-width:22px;text-align:center}
.rank-pos.gold-medal{color:var(--gold);font-size:.85rem}
.rank-info{flex:1;min-width:0}
.rank-name{font-size:.72rem;color:var(--text);line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rank-cat{font-size:.58rem;color:var(--muted2);margin-top:1px}
.rank-val{font-family:'JetBrains Mono',monospace;font-size:.76rem;font-weight:600;white-space:nowrap}
.rank-val.pos{color:var(--green)}.rank-val.neg{color:var(--red)}.rank-val.zero{color:var(--muted)}
.rank-empty{padding:24px 18px;text-align:center;color:var(--muted);font-size:.75rem}

/* ── CONTROLES ── */
.controls-bar{display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.search-wrap{position:relative;flex:1;min-width:220px}
.search-wrap svg{position:absolute;left:13px;top:50%;transform:translateY(-50%);color:var(--muted);pointer-events:none}
#searchInput{width:100%;padding:10px 14px 10px 40px;background:var(--bg2);border:1px solid var(--border);
  border-radius:10px;color:var(--text);font-family:'Inter',sans-serif;font-size:.85rem;
  outline:none;transition:border-color .2s,box-shadow .2s}
#searchInput:focus{border-color:var(--gold);box-shadow:0 0 0 3px var(--gold-dim)}
#searchInput::placeholder{color:var(--muted2)}
.ctrl-select{padding:10px 13px;background:var(--bg2);border:1px solid var(--border);border-radius:10px;
  color:var(--text);font-family:'Inter',sans-serif;font-size:.82rem;outline:none;cursor:pointer;transition:border-color .2s}
.ctrl-select:hover{border-color:var(--gold)}.ctrl-select option{background:var(--bg3)}
.toggle-wrap{display:flex;align-items:center;gap:8px}
.toggle-label{font-size:.76rem;color:var(--muted);white-space:nowrap;user-select:none}
.toggle{position:relative;width:36px;height:20px}.toggle input{opacity:0;width:0;height:0}
.toggle-slider{position:absolute;inset:0;background:var(--bg3);border:1px solid var(--border2);border-radius:20px;cursor:pointer;transition:.2s}
.toggle-slider::before{content:'';position:absolute;width:14px;height:14px;left:2px;top:2px;
  background:var(--muted2);border-radius:50%;transition:.2s}
.toggle input:checked+.toggle-slider{background:var(--gold-dim);border-color:var(--gold)}
.toggle input:checked+.toggle-slider::before{transform:translateX(16px);background:var(--gold)}

/* ── FILTROS ── */
.filter-section{display:flex;flex-direction:column;gap:8px}
.filter-row{display:flex;flex-wrap:wrap;gap:7px;align-items:center}
.filter-label{font-size:.6rem;text-transform:uppercase;letter-spacing:.1em;color:var(--muted2);
  font-weight:600;min-width:58px;white-space:nowrap}
.chip{padding:5px 13px;border-radius:20px;border:1px solid var(--border2);background:transparent;
  color:var(--muted);font-family:'Inter',sans-serif;font-size:.72rem;font-weight:500;
  cursor:pointer;transition:all .18s;white-space:nowrap}
.chip:hover{border-color:var(--gold);color:var(--gold)}.chip.active{background:var(--gold-dim);border-color:var(--gold);color:var(--gold2)}
.chip.pf:hover,.chip.pf.active{border-color:var(--green);color:var(--green);background:var(--green-dim)}
.chip.pj:hover,.chip.pj.active{border-color:var(--blue);color:var(--blue);background:var(--blue-dim)}
.chip.gov:hover,.chip.gov.active{border-color:var(--orange);color:var(--orange);background:rgba(251,146,60,.1)}
.chip.rpps:hover,.chip.rpps.active{border-color:var(--purple);color:var(--purple);background:rgba(167,139,250,.1)}
.chip.cons:hover,.chip.cons.active{border-color:var(--green);color:var(--green);background:var(--green-dim)}
.chip.mod:hover,.chip.mod.active{border-color:var(--blue);color:var(--blue);background:var(--blue-dim)}
.chip.arr:hover,.chip.arr.active{border-color:var(--orange);color:var(--orange);background:rgba(251,146,60,.1)}
.chip.agr:hover,.chip.agr.active{border-color:var(--red);color:var(--red);background:var(--red-dim)}

/* Filtro de performance */
.perf-period-select{padding:5px 10px;background:var(--bg2);border:1px solid var(--border);border-radius:8px;
  color:var(--text);font-family:'Inter',sans-serif;font-size:.72rem;outline:none;cursor:pointer;transition:border-color .2s;height:30px}
.perf-period-select:hover{border-color:var(--gold)}.perf-period-select option{background:var(--bg3)}

/* ── TABELA ── */
.table-wrap{border:1px solid var(--border);border-radius:14px;overflow:hidden;overflow-x:auto;
  background:var(--bg2);box-shadow:0 4px 40px rgba(0,0,0,.3)}
table{width:100%;border-collapse:collapse;min-width:1100px}
thead tr{background:linear-gradient(90deg,var(--bg4),var(--bg3));border-bottom:1px solid var(--border)}
th{padding:13px 15px;text-align:left;font-weight:600;font-size:.62rem;letter-spacing:.1em;
  text-transform:uppercase;color:var(--gold);white-space:nowrap;cursor:pointer;user-select:none;transition:color .15s}
th:hover{color:var(--gold2)}
th .si{opacity:.3;margin-left:3px;font-size:.55rem}
th.sa .si::after{content:' ▲';opacity:1}th.sd .si::after{content:' ▼';opacity:1}
th.sa,th.sd{color:var(--gold2)}
tbody tr{border-bottom:1px solid var(--border2);transition:background .12s}
tbody tr:last-child{border-bottom:none}tbody tr:hover{background:rgba(200,151,58,.03)}
tbody tr.row-sem-dados{opacity:.28}
tbody tr.detail-row{background:var(--bg3)}
tbody tr.detail-row:hover{background:var(--bg3)}
td{padding:11px 15px;font-family:'JetBrains Mono',monospace;font-size:.76rem;color:var(--text);white-space:nowrap}
td.col-fundo{font-family:'Inter',sans-serif;font-size:.8rem;white-space:normal;max-width:300px;font-weight:500;line-height:1.4}
td.col-fundo a{color:var(--text);text-decoration:none;display:inline-flex;align-items:flex-start;gap:5px;transition:color .15s}
td.col-fundo a:hover{color:var(--gold2)}
.link-icon{flex-shrink:0;margin-top:3px;opacity:0;transition:opacity .15s;color:var(--gold)}
tbody tr:hover .link-icon{opacity:1}
.link-fallback{font-size:.58rem;color:var(--muted2);margin-left:3px;opacity:.55;font-style:italic}
.exp-btn{background:transparent;border:none;color:var(--muted2);cursor:pointer;font-size:.7rem;
  padding:2px 5px;border-radius:4px;transition:color .15s,background .15s;line-height:1}
.exp-btn:hover{color:var(--gold);background:var(--gold-dim)}
td.col-cat{font-family:'Inter',sans-serif}
.cat-badge{display:inline-block;padding:3px 8px;border-radius:6px;font-size:.6rem;font-weight:600;
  letter-spacing:.04em;white-space:nowrap;border:1px solid transparent}
.cat-RF-S{background:rgba(46,209,122,.08);color:#2ed17a;border-color:rgba(46,209,122,.2)}
.cat-RF{background:rgba(91,156,246,.08);color:#5b9cf6;border-color:rgba(91,156,246,.2)}
.cat-RF-R{background:rgba(167,139,250,.08);color:#a78bfa;border-color:rgba(167,139,250,.2)}
.cat-RF-CP{background:rgba(56,189,248,.08);color:#38bdf8;border-color:rgba(56,189,248,.2)}
.cat-MM{background:rgba(251,146,60,.08);color:#fb923c;border-color:rgba(251,146,60,.2)}
.cat-CAM{background:rgba(250,204,21,.08);color:#facc15;border-color:rgba(250,204,21,.2)}
.cat-AC{background:rgba(244,114,182,.08);color:#f472b6;border-color:rgba(244,114,182,.2)}
.cat-ETF{background:rgba(45,212,191,.08);color:#2dd4bf;border-color:rgba(45,212,191,.2)}
.cat-FMP{background:rgba(232,121,249,.08);color:#e879f9;border-color:rgba(232,121,249,.2)}
td.col-pct{text-align:center}
.pct-wrap{display:flex;align-items:center;justify-content:center;gap:5px}
.pct-bar-bg{width:28px;height:3px;background:var(--bg3);border-radius:2px;overflow:hidden;flex-shrink:0}
.pct-bar{height:100%;border-radius:2px}.pct-bar.pos{background:var(--green)}.pct-bar.neg{background:var(--red)}
.pct-val{font-size:.76rem;min-width:52px;text-align:center}
.pct-val.pos{color:var(--green);font-weight:600}.pct-val.neg{color:var(--red);font-weight:600}.pct-val.zero{color:var(--muted)}
.dash{color:var(--muted2);font-size:.68rem}
.perfis-wrap{display:flex;flex-wrap:wrap;gap:3px}
.perfil-chip{display:inline-block;padding:2px 6px;border-radius:4px;font-family:'Inter',sans-serif;
  font-size:.58rem;font-weight:600;letter-spacing:.04em;white-space:nowrap}
.pchip-PF{background:rgba(46,209,122,.1);color:#2ed17a}
.pchip-PJ{background:rgba(91,156,246,.1);color:#5b9cf6}
.pchip-GOV{background:rgba(251,146,60,.1);color:#fb923c}
.pchip-RPPS{background:rgba(167,139,250,.1);color:#a78bfa}
.pchip-TODOS{background:rgba(200,151,58,.1);color:var(--gold)}

