.sinal-cdi{color:var(--green);background:rgba(46,209,122,.10);border-color:rgba(46,209,122,.18)}
.sinal-ipca{color:var(--purple);background:rgba(167,139,250,.10);border-color:rgba(167,139,250,.18)}
.sinal-cambio{color:#facc15;background:rgba(250,204,21,.10);border-color:rgba(250,204,21,.18)}
.sinal-cred{color:#e879f9;background:rgba(232,121,249,.10);border-color:rgba(232,121,249,.18)}
.sinal-duration{color:var(--orange);background:rgba(251,146,60,.10);border-color:rgba(251,146,60,.20)}
.sinal-rv{color:var(--red);background:rgba(240,85,101,.10);border-color:rgba(240,85,101,.18)}
@media(max-width:768px){.col-sinais{min-width:180px}.sinais-wrap{max-width:220px}.sinal-chip{font-size:.54rem;padding:3px 6px}}

/* ── DETAIL PANEL ── */
.detail-panel{padding:14px 18px;display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:16px;animation:fadeUp .2s ease;align-items:start}
.detail-main{display:flex;flex-wrap:wrap;gap:16px;min-width:0}
.detail-item{display:flex;flex-direction:column;gap:3px;min-width:120px}
.detail-key{font-size:.58rem;text-transform:uppercase;letter-spacing:.1em;color:var(--muted2);font-weight:600}
.detail-val{font-family:'JetBrains Mono',monospace;font-size:.72rem;color:var(--text)}
.detail-val a{color:var(--blue);text-decoration:none}.detail-val a:hover{text-decoration:underline}
.detail-val.copyable{user-select:all}

.detail-panel{
  grid-template-columns:1fr !important;
  white-space:normal !important;
}
.detail-main{
  white-space:normal !important;
  overflow:visible !important;
}
.fund-quick-note{
  white-space:normal !important;
  overflow:visible !important;
  word-break:normal;
}
.fund-quick-note-text{
  white-space:normal !important;
  overflow:visible !important;
  display:block;
}
.docs-mini-wrap{
  display:flex;
  align-items:center;
  gap:4px;
  flex-wrap:wrap;
  max-width:230px;
}
.doc-mini,
.doc-mini-all{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-width:26px;
  height:22px;
  padding:0 6px;
  border-radius:6px;
  border:1px solid var(--border2);
  background:var(--bg3);
  color:var(--muted);
  font-size:.58rem;
  font-family:'Inter',sans-serif;
  font-weight:700;
  text-decoration:none;
  cursor:pointer;
  transition:all .15s;
}
.doc-mini:hover,
.doc-mini-all:hover{
  border-color:var(--gold);
  color:var(--gold2);
  background:var(--gold-dim);
  text-decoration:none;
}
.doc-mini-all{
  color:var(--gold2);
  background:var(--gold-dim);
  border-color:var(--border);
  min-width:42px;
}
.doc-mini-empty{
  color:var(--muted2);
  font-size:.65rem;
}


.fund-quick-note{
  width:100%;
  margin-top:2px;
  padding:12px 14px;
  border:1px solid var(--border2);
  border-radius:12px;
  background:rgba(91,156,246,.045);
  color:var(--muted);
  line-height:1.55;
  font-size:.68rem;
}
.fund-quick-note-title{
  display:flex;
  align-items:center;
  gap:6px;
  margin-bottom:6px;
  font-size:.58rem;
  text-transform:uppercase;
  letter-spacing:.1em;
  color:var(--gold);
  font-weight:700;
}
.fund-quick-note-text{
  color:var(--text);
  font-size:.72rem;
}
.fund-quick-note-disclaimer{
  margin-top:7px;
  color:var(--muted2);
  font-family:'JetBrains Mono',monospace;
  font-size:.54rem;
  line-height:1.45;
}

/* ── DOCUMENTOS DO FUNDO — lateral compacta ── */
.docs-card{width:100%;padding:12px;background:rgba(255,255,255,.018);border:1px solid var(--border2);border-radius:12px;position:sticky;top:10px}
.docs-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:10px}
.docs-title{font-size:.58rem;text-transform:uppercase;letter-spacing:.1em;color:var(--gold);font-weight:700;line-height:1.35}
.docs-actions{display:flex;gap:5px;flex-wrap:wrap;justify-content:flex-end}
.docs-action-btn{border:1px solid var(--border);background:var(--gold-dim);color:var(--gold2);border-radius:7px;padding:5px 8px;font-size:.6rem;font-family:'Inter',sans-serif;font-weight:600;cursor:pointer;transition:all .15s;white-space:nowrap}
.docs-action-btn:hover{border-color:var(--gold2);background:rgba(200,151,58,.18)}
.docs-action-btn.secondary{background:var(--bg3);color:var(--muted);border-color:var(--border2)}
.docs-action-btn.secondary:hover{color:var(--blue);border-color:var(--blue);background:var(--blue-dim)}
.docs-grid{display:flex;flex-direction:column;gap:6px}
.doc-pill{display:flex;align-items:center;gap:8px;padding:6px 9px;border:1px solid var(--border2);border-radius:9px;background:var(--bg2);min-width:0;transition:border-color .15s,background .15s}
.doc-pill:hover{border-color:rgba(200,151,58,.28);background:rgba(200,151,58,.045)}
.doc-pill input{accent-color:var(--gold);width:13px;height:13px;flex-shrink:0}
.doc-pill a{color:var(--text);text-decoration:none;font-size:.66rem;font-family:'Inter',sans-serif;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.doc-pill a:hover{color:var(--gold2);text-decoration:none}
.docs-note{margin-top:8px;font-size:.54rem;color:var(--muted2);font-family:'JetBrains Mono',monospace;line-height:1.45}
@media(max-width:900px){
  .detail-panel{grid-template-columns:1fr}
  .docs-card{position:static}
}



/* ── RANKINGS COMPACTOS + COMPARTILHAMENTO ── */
.ranking-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  flex-wrap:wrap;
  gap:10px;
  margin-bottom:12px;
}
.ranking-title-group{
  display:flex;
  align-items:center;
  gap:10px;
  flex-wrap:wrap;
  min-width:0;
}
.ranking-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  flex-wrap:wrap;
  gap:6px;
}
.ranking-action-btn,
.rank-action-btn,
.rank-more-btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:5px;
  border:1px solid var(--border2);
  background:rgba(17,21,38,.78);
  color:#b4bdd3;
  border-radius:8px;
  padding:6px 10px;
  font-family:'Inter',sans-serif;
  font-size:.64rem;
  font-weight:700;
  line-height:1;
  cursor:pointer;
  transition:all .15s;
  white-space:nowrap;
}
.ranking-action-btn:hover,
.rank-action-btn:hover,
.rank-more-btn:hover{
  color:var(--gold2);
  border-color:rgba(232,187,106,.55);
  background:rgba(200,151,58,.14);
}
.ranking-grid{
  grid-template-columns:repeat(auto-fit,minmax(245px,1fr));
  gap:10px;
}
.rank-card{
  border-radius:12px;
}
.rank-card-header{
  padding:11px 12px 8px;
  gap:8px;
  justify-content:space-between;
}
.rank-card-title-wrap{
  display:flex;
  align-items:center;
  gap:7px;
  min-width:0;
}
.rank-card-title{
  font-size:.90rem;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.rank-card-actions{
  display:flex;
  align-items:center;
  gap:4px;
  flex-shrink:0;
}
.rank-action-btn{
  padding:5px 7px;
  font-size:.58rem;
  border-radius:7px;
}
.rank-card-sub{
  padding:4px 12px 1px;
  color:var(--muted2);
  font-size:.56rem;
  font-family:'JetBrains Mono',monospace;
  line-height:1.35;
}
.rank-list{
  padding:2px 0;
}
.rank-item{
  gap:8px;
  padding:7px 12px;
}
.rank-pos{
  min-width:20px;
  font-size:.60rem;
}
.rank-name{
  font-size:.68rem;
  line-height:1.25;
}
.rank-cat{
  font-size:.54rem;
  line-height:1.25;
}
.rank-val{
  font-size:.70rem;
  max-width:86px;
  overflow:hidden;
  text-overflow:ellipsis;
}
.rank-card.rank-collapsed .rank-list .rank-item:nth-of-type(n+6){
  display:none;
}
.rank-more-wrap{
  padding:6px 12px 10px;
  border-top:1px solid var(--border2);
}
.rank-more-btn{
  width:100%;
  padding:7px 8px;
  font-size:.62rem;
  color:var(--muted);
}
.rank-share-toast{
  position:fixed;
  left:50%;
  bottom:18px;
  z-index:2000;
  transform:translateX(-50%) translateY(20px);
  opacity:0;
  pointer-events:none;
  padding:10px 14px;
  border-radius:10px;
  border:1px solid rgba(46,209,122,.26);
  background:rgba(12,14,26,.96);
  color:#c9f6dc;
  font-size:.72rem;
  box-shadow:0 10px 40px rgba(0,0,0,.45);
  transition:opacity .2s, transform .2s;
}
.rank-share-toast.show{
  opacity:1;
  transform:translateX(-50%) translateY(0);
}
@media(max-width:768px){
  .ranking-head{align-items:flex-start}
  .ranking-title-group{width:100%}
  .ranking-actions{width:100%;justify-content:flex-start;overflow-x:auto;flex-wrap:nowrap;padding-bottom:4px;-webkit-overflow-scrolling:touch}
  .ranking-action-btn{flex:0 0 auto}
  .ranking-grid{grid-template-columns:1fr;gap:9px}
  .rank-card-header{padding:10px 11px 7px}
  .rank-card-title{font-size:.86rem}
  .rank-action-btn{font-size:.56rem;padding:5px 6px}
  .rank-item{padding:7px 11px}
  .rank-name{font-size:.67rem;white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
  .rank-val{font-size:.69rem;max-width:78px}
}

/* ── PAGINAÇÃO ── */
.pagination-row{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-top:20px;padding:0 2px}
#resultInfo{font-size:.7rem;color:var(--muted);font-family:'JetBrains Mono',monospace}
.page-btns{display:flex;gap:4px}
.page-btn{width:32px;height:32px;display:flex;align-items:center;justify-content:center;
  border-radius:7px;border:1px solid var(--border2);background:transparent;color:var(--muted);
  font-family:'Inter',sans-serif;font-size:.8rem;cursor:pointer;transition:all .15s}
.page-btn:hover:not(:disabled){border-color:var(--gold);color:var(--gold);background:var(--gold-dim)}
.page-btn.active{background:var(--gold-dim);border-color:var(--gold);color:var(--gold2)}
.page-btn:disabled{opacity:.2;cursor:default}

/* ── MODAL PTAX ── */
.modal-overlay{position:fixed;inset:0;z-index:1000;background:rgba(0,0,0,.75);backdrop-filter:blur(4px);
  display:flex;align-items:center;justify-content:center;padding:20px;opacity:0;pointer-events:none;transition:opacity .2s}
.modal-overlay.open{opacity:1;pointer-events:all}
.modal{background:var(--bg2);border:1px solid var(--border);border-radius:18px;width:100%;max-width:720px;
  max-height:85vh;display:flex;flex-direction:column;overflow:hidden;
  transform:translateY(20px);transition:transform .25s;box-shadow:0 24px 80px rgba(0,0,0,.6)}
.modal-overlay.open .modal{transform:translateY(0)}
.modal-header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px 14px;
  border-bottom:1px solid var(--border2)}
.modal-title{font-family:'Cormorant Garamond',serif;font-size:1.2rem;font-weight:700;color:var(--gold2)}
.modal-close{background:transparent;border:none;color:var(--muted);font-size:1.2rem;cursor:pointer;
  padding:4px 8px;border-radius:6px;transition:color .15s,background .15s;line-height:1}
.modal-close:hover{color:var(--text);background:var(--bg3)}
.modal-body{overflow-y:auto;padding:0}
.modal-footer{padding:12px 24px;border-top:1px solid var(--border2);font-size:.62rem;color:var(--muted2);
  font-family:'JetBrains Mono',monospace;font-style:italic}
.ptax-table{width:100%;border-collapse:collapse}
.ptax-table thead tr{background:var(--bg3);position:sticky;top:0;z-index:1}
.ptax-table th{padding:10px 16px;font-size:.6rem;text-transform:uppercase;letter-spacing:.1em;
  color:var(--gold);font-weight:600;text-align:right;white-space:nowrap}
.ptax-table th:first-child{text-align:left}
.ptax-table tbody tr{border-bottom:1px solid var(--border2);transition:background .12s}
.ptax-table tbody tr:hover{background:rgba(200,151,58,.04)}
.ptax-table td{padding:10px 16px;font-family:'JetBrains Mono',monospace;font-size:.78rem;text-align:right}
.ptax-table td:first-child{text-align:left;font-family:'Inter',sans-serif;font-size:.8rem;font-weight:500}
.ptax-month{color:var(--text)}
.ptax-val{color:var(--gold2);font-weight:600}
.ptax-var.pos{color:var(--green)}.ptax-var.neg{color:var(--red)}.ptax-var.zero{color:var(--muted)}
.ptax-loading{text-align:center;padding:40px;color:var(--muted);font-size:.8rem}

/* ── LOADING ── */
#loadMsg{text-align:center;padding:70px 20px;color:var(--muted);font-size:.85rem}
.spinner{width:32px;height:32px;margin:0 auto 18px;border:2px solid var(--border);
  border-top-color:var(--gold);border-radius:50%;animation:spin .75s linear infinite}
.spinner-sm{width:16px;height:16px;border:2px solid var(--border2);border-top-color:var(--gold);
  border-radius:50%;animation:spin .75s linear infinite;display:inline-block;vertical-align:middle;margin-right:6px}

/* ── BOTÃO AUXILIAR DE LINK ── */
.boletim-btn{display:inline-flex;align-items:center;gap:3px;padding:2px 7px;
  border:1px solid var(--border2);border-radius:5px;background:transparent;
  color:var(--muted2);font-size:.6rem;font-family:'Inter',sans-serif;cursor:pointer;
  text-decoration:none;transition:all .15s;white-space:nowrap}
.boletim-btn:hover{border-color:var(--blue);color:var(--blue);background:var(--blue-dim)}

/* ── PTAX BUTTON ── */
.ptax-btn{display:inline-flex;align-items:center;gap:5px;padding:4px 10px;
  border:1px solid var(--border);border-radius:6px;background:var(--bg3);color:var(--muted);
  font-size:.62rem;font-family:'Inter',sans-serif;cursor:pointer;transition:all .15s;white-space:nowrap}
.ptax-btn:hover{border-color:var(--gold);color:var(--gold);background:var(--gold-dim)}

/* ── FOOTER ── */
footer{
  margin-top:60px;
  padding-top:30px;
  border-top:1px solid rgba(200,151,58,.16);
}
.footer-disclaimer{
  max-width:1180px;
  margin:0 auto;
  padding:22px 26px;
  border:1px solid rgba(200,151,58,.18);
  border-radius:16px;
  background:linear-gradient(180deg,rgba(200,151,58,.075),rgba(255,255,255,.018));
  color:#aeb7cf;
  font-size:.74rem;
  line-height:1.75;
  text-align:left;
  box-shadow:0 10px 40px rgba(0,0,0,.22);
}
.footer-disclaimer-title{
  color:var(--gold2);
  font-family:'Cormorant Garamond',serif;
  font-size:1.15rem;
  font-weight:700;
  margin-bottom:10px;
  letter-spacing:.02em;
}
.footer-disclaimer p{
  margin:8px 0;
}
.footer-disclaimer strong{
  color:var(--text);
  font-weight:600;
}
.footer-disclaimer-signature{
  margin-top:14px;
  padding-top:12px;
  border-top:1px solid rgba(255,255,255,.07);
  color:var(--gold2);
  font-size:.68rem;
  letter-spacing:.04em;
}

/* ── RESPONSIVO ── */
@media(max-width:768px){
  .page{padding:18px 14px 60px}
  .top-disclaimer{font-size:.7rem;padding:12px 14px}
  .dolar-source-note,.dolar-chart-source{align-items:flex-start;font-size:.61rem;margin-left:12px;margin-right:12px}
  .footer-disclaimer{padding:18px 18px;font-size:.7rem}
  .kpi-grid{grid-template-columns:1fr 1fr;gap:10px}
  .kpi-value{font-size:1.5rem}
  .focus-grid{grid-template-columns:1fr 1fr}
  .ranking-grid{grid-template-columns:1fr}
  .indic-ref-card{min-width:100%}
}
@media(max-width:480px){
  .focus-grid{grid-template-columns:1fr}
  .kpi-grid{grid-template-columns:1fr}
}

/* ── TABELA DE INDICADORES v2 — linha do tempo ── */
.indic-table-v2{width:100%;border-collapse:collapse;min-width:680px}
.indic-table-v2 thead tr{background:linear-gradient(90deg,var(--bg4),var(--bg3));border-bottom:1px solid var(--border)}
.indic-table-v2 th{padding:10px 14px;font-size:.6rem;text-transform:uppercase;letter-spacing:.08em;color:var(--gold);font-weight:600;text-align:right;white-space:nowrap;line-height:1.5}
.indic-table-v2 th:first-child{text-align:left;min-width:200px}
.indic-table-v2 th.th-cur{background:rgba(91,156,246,.08);color:var(--blue)}
.indic-table-v2 th.th-acum{color:var(--gold2)}
.th-sub{font-size:.58rem;font-weight:400;opacity:.7;font-family:'JetBrains Mono',monospace;text-transform:none;letter-spacing:0}
.indic-table-v2 .group-row td{padding:8px 14px 6px;background:rgba(17,21,38,.82);border-bottom:1px solid var(--border2);border-top:2px solid var(--border)}
.group-lbl{display:flex;align-items:center;gap:10px;font-size:.62rem;text-transform:uppercase;letter-spacing:.1em;color:#c8c0a8;font-weight:700}
.group-lbl-line{flex:1;height:1px;background:var(--border2)}
.market-flag{display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;margin-right:6px;font-size:.86rem;vertical-align:middle;filter:saturate(1.08)}
.indic-table-v2 tbody tr.data-row{border-bottom:1px solid var(--border2);transition:background .12s}
.indic-table-v2 tbody tr.data-row:hover{background:rgba(200,151,58,.03)}
.indic-table-v2 tbody tr.data-row.alert-row{background:transparent}
.indic-table-v2 tbody tr.data-row.alert-row:hover{background:rgba(231,185,95,.035)}
.indic-table-v2 td{padding:12px 14px;text-align:right;vertical-align:middle}
.indic-table-v2 td:first-child{text-align:left}
.indic-table-v2 td.td-cur{background:rgba(91,156,246,.04)}
.ind-name-v2{display:flex;align-items:flex-start;gap:8px}
.ind-icon-v2{width:28px;height:28px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:.9rem;margin-top:1px}
.ii-blue{background:rgba(91,156,246,.12)}.ii-red{background:rgba(240,85,101,.12)}
.ii-amber{background:rgba(200,151,58,.12)}.ii-teal{background:rgba(46,209,122,.12)}.ii-purple{background:rgba(167,139,250,.12)}
.ind-v2-title{font-size:.84rem;font-weight:600;color:var(--text);line-height:1.3}
.ind-v2-sub{font-size:.62rem;color:#8a95b2;margin-top:2px;font-family:'JetBrains Mono',monospace}
.badge-partial{display:inline-block;padding:1px 6px;border-radius:4px;background:rgba(91,156,246,.12);color:var(--blue);font-size:.58rem;font-weight:600}
.badge-await{display:inline-block;padding:1px 6px;border-radius:4px;background:rgba(94,107,138,.15);color:var(--muted);font-size:.58rem;font-weight:600}
.badge-alrt{display:inline-block;padding:1px 6px;border-radius:4px;background:rgba(231,185,95,.16);color:var(--gold);font-size:.58rem;font-weight:700;margin-left:4px}
.v2-val{font-family:'Cormorant Garamond',serif;font-size:1.05rem;font-weight:700;line-height:1.2}
.v2-val.pos{color:#4de896}.v2-val.neg{color:#ff6b7a}.v2-val.neu{color:var(--text)}.v2-val.dash{color:var(--muted2);font-size:.75rem;font-family:'JetBrains Mono',monospace}
.v2-sub{font-size:.62rem;color:#9aa5c4;margin-top:3px;font-family:'JetBrains Mono',monospace}
.v2-bar-row{display:flex;align-items:center;justify-content:flex-end;gap:5px}
.v2-bar-bg{display:none}
.v2-bar-p{height:100%;border-radius:2px;background:var(--green)}.v2-bar-n{height:100%;border-radius:2px;background:var(--red)}



/* ─────────────────────────────────────────────
   AJUSTE DE LEGIBILIDADE — versão profissional
   Melhora contraste, tamanho de fonte e hierarquia visual.
───────────────────────────────────────────── */
body{
  font-weight:400;
  text-rendering:geometricPrecision;
}

.brand-text p,
.live-badge,
.section-badge,
.kpi-sub,
.indic-tabs-label,
.filter-label,
#resultInfo{
  color:var(--muted);
}

.live-badge,
.section-badge{
  border-color:rgba(255,255,255,.10);
  background:rgba(17,21,38,.72);
}

.kpi-label,
.indic-ref-label,
.poup-rule-label,
.fcad-label,
.indic-title,
.detail-key,
.docs-title{
  color:#9faccc;
  font-weight:700;
}

.kpi-label{
  font-size:.66rem;
  letter-spacing:.105em;
}

.kpi-sub{
  font-size:.70rem;
  line-height:1.45;
}

.section-title h2{
  font-size:1.22rem;
}

.section-badge{
  font-size:.66rem;
  padding:4px 10px;
}

.indic-ref-card{
  padding:22px 24px;
  border-color:rgba(200,151,58,.24);
  background:linear-gradient(180deg,rgba(17,21,38,.96),rgba(12,14,26,.96));
