/* ─────────────────────────────────────────────
   MELHORIAS DA SEÇÃO DE MERCADO — cards separados + resumo
───────────────────────────────────────────── */
.market-section-head{
  justify-content:space-between;
  align-items:center;
  gap:14px;
  flex-wrap:wrap;
  margin-bottom:14px;
}
.market-title-left{
  display:flex;
  align-items:center;
  gap:10px;
  flex-wrap:wrap;
  min-width:0;
}
.market-period-tabs{
  margin-bottom:0;
  margin-left:auto;
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
}
.market-period-tabs .indic-tabs-label{
  font-size:.64rem;
  color:#aeb7cf;
  font-family:'JetBrains Mono',monospace;
  white-space:nowrap;
}
.market-ref-grid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:12px;
  align-items:stretch;
  margin-bottom:12px;
}
.market-ref-card{
  min-width:0 !important;
  flex:none !important;
  display:flex;
  flex-direction:column;
  align-items:stretch;
  justify-content:flex-start;
  gap:0;
}
.selic-card::before{background:linear-gradient(90deg,var(--gold),transparent 72%)}
.cdi-card::before{background:linear-gradient(90deg,var(--green),transparent 72%)}
.poup.market-ref-card::before{background:linear-gradient(90deg,var(--blue),transparent 72%)}
.cdi-mini-grid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:8px;
  margin-top:12px;
  margin-bottom:6px;
}
.cdi-mini-item{
  padding:8px 10px;
  border:1px solid rgba(255,255,255,.085);
  border-radius:10px;
  background:rgba(17,21,38,.62);
  min-width:0;
}
.cdi-mini-item span{
  display:block;
  font-size:.56rem;
  color:var(--muted2);
  text-transform:uppercase;
  letter-spacing:.075em;
  margin-bottom:3px;
}
.cdi-mini-item strong{
  display:block;
  font-family:'JetBrains Mono',monospace;
  font-size:.78rem;
  color:var(--green);
  white-space:nowrap;
}
.market-scenario-card{
  display:flex;
  align-items:flex-start;
  gap:10px;
  margin:2px 0 12px;
  padding:12px 15px;
  border:1px solid rgba(200,151,58,.18);
  border-radius:14px;
  background:linear-gradient(180deg,rgba(200,151,58,.075),rgba(255,255,255,.018));
  color:#b8c0d6;
  font-size:.74rem;
  line-height:1.55;
  box-shadow:0 8px 28px rgba(0,0,0,.16);
}
.market-scenario-icon{
  flex-shrink:0;
  width:24px;
  height:24px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  border-radius:8px;
  background:rgba(200,151,58,.10);
  border:1px solid rgba(200,151,58,.18);
}
.market-scenario-card strong{
  color:var(--gold2);
  font-weight:700;
}
#marketScenarioText{
  color:#d5dbea;
}
@media(max-width:1100px){
  .market-ref-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .poup.market-ref-card{grid-column:1/-1}
}
@media(max-width:768px){
  .market-section-head{align-items:stretch}
  .market-title-left{width:100%}
  .market-period-tabs{
    width:100%;
