  .filter-row::-webkit-scrollbar,.ranking-actions::-webkit-scrollbar,.market-period-tabs .indic-tabs::-webkit-scrollbar{height:4px}
  .filter-row::-webkit-scrollbar-thumb,.ranking-actions::-webkit-scrollbar-thumb,.market-period-tabs .indic-tabs::-webkit-scrollbar-thumb{background:rgba(200,151,58,.28);border-radius:999px}
  .filter-label{flex:0 0 auto;min-width:auto;position:sticky;left:0;z-index:2;padding:6px 8px 6px 0;background:linear-gradient(90deg,var(--bg) 0%,rgba(7,8,15,.90) 78%,rgba(7,8,15,0) 100%)}
  .chip,.perf-period-select{flex:0 0 auto;scroll-snap-align:start;font-size:.68rem;padding:6px 11px}

  /* Tabela principal: ocupa a largura da tela e avisa que arrasta */
  .table-wrap{position:relative;width:100vw;max-width:100vw;margin-left:calc(50% - 50vw);border-left:0;border-right:0;border-radius:0;box-shadow:none;overflow-x:auto;-webkit-overflow-scrolling:touch}
  .table-wrap::before{content:'↔ arraste a tabela para ver mais colunas';position:sticky;left:0;z-index:4;display:block;width:max-content;max-width:100vw;padding:7px 12px;background:linear-gradient(90deg,rgba(12,14,26,.96),rgba(12,14,26,.74));color:#aeb7cf;font-family:'JetBrains Mono',monospace;font-size:.56rem;border-bottom:1px solid rgba(255,255,255,.07)}
  table{min-width:980px}
  th{padding:9px 10px;font-size:.54rem;letter-spacing:.075em}
  td{padding:9px 10px;font-size:.66rem}
  td.col-fundo{min-width:220px;max-width:220px;font-size:.70rem;line-height:1.32}
  .cat-badge{font-size:.54rem;padding:3px 7px}
  .pct-val{font-size:.68rem;min-width:46px}
  .pct-bar-bg{width:22px}
  .docs-mini-wrap{max-width:96px;gap:3px}
  .doc-mini,.doc-mini-all{min-width:23px;height:21px;padding:0 5px;font-size:.52rem}

  /* Painel consolidado: rolagem controlada, texto menor */
  .indic-table-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch;border-radius:12px}
  .indic-table-v2{min-width:920px}
