/* ─────────────────────────────────────────────
   PAINEL CONSOLIDADO — coluna fixa + leitura compacta
   Mantém o indicador visível ao arrastar a tabela no celular.
───────────────────────────────────────────── */
.indic-table-wrap{
  position:relative;
  overflow-x:auto;
  -webkit-overflow-scrolling:touch;
}
.indic-table-v2{
  border-collapse:separate;
  border-spacing:0;
  table-layout:fixed;
}
.indic-table-v2 th:first-child,
.indic-table-v2 td:first-child{
  position:sticky;
  left:0;
  z-index:6;
  width:230px;
  min-width:230px;
  max-width:230px;
  background:linear-gradient(90deg,rgba(12,14,26,.99),rgba(12,14,26,.96));
  box-shadow:12px 0 18px rgba(0,0,0,.38);
}
