  z-index:8;
  background:linear-gradient(90deg,var(--bg4),var(--bg3));
}
.indic-table-v2 .group-row td{
  position:sticky;
  left:0;
  z-index:7;
  width:auto;
  min-width:230px;
  max-width:none;
  background:linear-gradient(90deg,var(--bg3),rgba(17,21,38,.98));
  box-shadow:12px 0 18px rgba(0,0,0,.32);
}
.indic-table-v2 th:not(:first-child),
.indic-table-v2 td:not(:first-child){
  min-width:120px;
  width:120px;
  max-width:120px;
}
.indic-table-v2 td:not(:first-child){
  vertical-align:middle;
}
.indic-table-v2 .v2-bar-row{
  gap:5px;
}

