/* ─────────────────────────────────────────────
   POUPANÇA — gráfico de cenários das regras
   Card didático ao lado da poupança: compara regra nova x antiga
───────────────────────────────────────────── */
.poup-card-consultivo{
  grid-column:span 2;
}
.poup-scenarios-card{
  grid-column:span 1;
  gap:12px !important;
  position:relative;
  overflow:hidden;
}
.poup-scenarios-card::before{
  background:linear-gradient(90deg,var(--blue),var(--gold),transparent 78%) !important;
}
.poup-scenarios-head{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:10px;
}
.poup-scenarios-title{
  min-width:0;
}
.poup-scenarios-subtitle{
  margin-top:3px;
  color:#a6b0c9;
  font-size:.61rem;
  line-height:1.35;
  font-family:'JetBrains Mono',monospace;
}
.poup-scenario-status{
  flex-shrink:0;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  padding:4px 8px;
  border-radius:999px;
  border:1px solid rgba(91,156,246,.24);
  background:rgba(91,156,246,.09);
  color:#8bbfff;
  font-size:.56rem;
  font-family:'JetBrains Mono',monospace;
  font-weight:800;
  white-space:nowrap;
}
.poup-scenario-summary{
  padding:9px 11px;
  border:1px solid rgba(200,151,58,.16);
  border-radius:11px;
  background:rgba(200,151,58,.055);
  color:#d8c79f;
  font-size:.68rem;
  line-height:1.55;
  font-family:'Inter',sans-serif;
  font-weight:500;
}
.poup-scenario-chart-wrap{
  height:195px;
  min-height:185px;
  padding:10px 8px 4px;
  border:1px solid rgba(255,255,255,.075);
  border-radius:12px;
  background:rgba(17,21,38,.46);
}
.poup-scenario-chart-wrap canvas{
  width:100% !important;
  height:100% !important;
  display:block;
}
.poup-scenario-metrics{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:8px;
}
.poup-scenario-pill{
  min-width:0;
  padding:8px 9px;
  border:1px solid rgba(255,255,255,.075);
  border-radius:10px;
  background:rgba(255,255,255,.025);
}
.poup-scenario-pill span{
  display:block;
  margin-bottom:4px;
  color:#aeb7cf;
  font-size:.60rem;
  font-family:'Inter',sans-serif;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:.045em;
  line-height:1.25;
}
.poup-scenario-pill strong{
  display:block;
  color:#f2f5ff;
  font-size:.82rem;
  font-family:'Inter',sans-serif;
  font-weight:600;
  letter-spacing:0;
  line-height:1.28;
  text-rendering:geometricPrecision;
}
.poup-scenario-note{
  color:#98a3bf;
  font-size:.60rem;
  font-family:'Inter',sans-serif;
  font-weight:500;
  line-height:1.5;
}
@media(max-width:1100px){
  .poup-card-consultivo,
  .poup-scenarios-card{
    grid-column:1/-1;
  }
  .poup-scenario-chart-wrap{
    height:210px;
  }
}
@media(max-width:768px), (pointer:coarse){
  .poup-card-consultivo,
  .poup-scenarios-card{
    grid-column:1/-1 !important;
  }
  .market-ref-card:nth-child(4){
    grid-column:1/-1 !important;
  }
  .poup-scenario-chart-wrap{
    height:205px;
    min-height:195px;
  }
  .poup-scenario-metrics{
    grid-template-columns:1fr;
    gap:7px;
  }
  .poup-scenarios-subtitle{
    font-size:.58rem;
  }
  .poup-scenario-summary,
  .poup-scenario-note{
    font-size:.62rem;
  }
}
@media(max-width:430px){
  .poup-scenarios-head{
    flex-direction:column;
    align-items:flex-start;
  }
  .poup-scenario-status{
    font-size:.52rem;
  }
}



/* ─────────────────────────────────────────────
   PATCH — Painel de indicadores com 1ª coluna realmente fixa no mobile
   Correção: evita que as colunas de dados passem por cima/por baixo do texto
   do indicador ao arrastar horizontalmente.
───────────────────────────────────────────── */
.indic-table-wrap{
  position:relative !important;
  display:block !important;
  width:100% !important;
  max-width:100% !important;
  overflow-x:auto !important;
  overflow-y:hidden !important;
  -webkit-overflow-scrolling:touch !important;
  overscroll-behavior-x:contain;
  isolation:isolate;
  background:var(--bg2);
}

.indic-table-v2{
  border-collapse:separate !important;
  border-spacing:0 !important;
  table-layout:fixed !important;
}

.indic-table-v2 th:first-child,
.indic-table-v2 td:first-child{
  position:-webkit-sticky !important;
  position:sticky !important;
  left:0 !important;
  z-index:30 !important;
  background:#0c0e1a !important;
  background-image:linear-gradient(90deg,rgba(12,14,26,1) 0%,rgba(12,14,26,.99) 78%,rgba(12,14,26,.94) 100%) !important;
  background-clip:padding-box !important;
  box-shadow:14px 0 20px rgba(0,0,0,.55) !important;
  overflow:hidden !important;
  transform:translateZ(0);
}

.indic-table-v2 thead th:first-child{
  z-index:60 !important;
  background:#181d36 !important;
  background-image:linear-gradient(90deg,var(--bg4),var(--bg3)) !important;
}

.indic-table-v2 tbody tr.data-row td:first-child{
  z-index:40 !important;
}

.indic-table-v2 th:not(:first-child),
.indic-table-v2 td:not(:first-child){
  position:relative;
  z-index:1;
}

.indic-table-v2 td.td-cur,
.indic-table-v2 th.th-cur{
  z-index:2;
}

.indic-table-v2 th:first-child::after,
.indic-table-v2 tbody tr.data-row td:first-child::after{
  content:'';
  position:absolute;
  top:0;
  right:-1px;
  bottom:0;
  width:18px;
  pointer-events:none;
  background:linear-gradient(90deg,rgba(12,14,26,0),rgba(0,0,0,.38));
}

.indic-table-v2 .ind-name-v2{
  position:relative;
  z-index:2;
  min-width:0;
  max-width:100%;
}

.indic-table-v2 .ind-text-v2{
  min-width:0;
  max-width:100%;
  overflow:hidden;
}

.indic-table-v2 .ind-title-v2,
.indic-table-v2 .ind-sub-v2{
  max-width:100%;
  overflow:hidden;
  text-overflow:ellipsis;
}

.indic-table-v2 .group-row td{
  position:-webkit-sticky !important;
  position:sticky !important;
  left:0 !important;
  z-index:55 !important;
  background:#111526 !important;
  background-image:linear-gradient(90deg,var(--bg3) 0%,rgba(17,21,38,.99) 72%,rgba(17,21,38,.92) 100%) !important;
  box-shadow:14px 0 20px rgba(0,0,0,.45) !important;
  transform:translateZ(0);
}

@media (max-width:760px), (pointer:coarse){
  .indic-table-v2 th:first-child,
  .indic-table-v2 td:first-child{
    width:188px !important;
    min-width:188px !important;
    max-width:188px !important;
  }

  .indic-table-v2 .group-row td{
    min-width:188px !important;
  }

  .indic-table-v2 th:not(:first-child),
  .indic-table-v2 td:not(:first-child){
    width:112px !important;
    min-width:112px !important;
    max-width:112px !important;
  }

  .indic-table-v2{
    min-width:748px !important;
  }

  .indic-table-v2 .ind-title-v2{
    white-space:nowrap;
  }

  .indic-table-v2 .ind-sub-v2{
    display:-webkit-box;
    -webkit-line-clamp:2;
    -webkit-box-orient:vertical;
    white-space:normal;
    line-height:1.25;
  }
}



