/* ════════════════════════════════════════════════════
   PATCH DE LEGIBILIDADE GERAL — dark mode/mobile
   Objetivo: reduzir efeito "borrado" de JetBrains Mono pequeno/negrito
   em textos explicativos, labels e botões. Mantém mono em números/tabelas.
════════════════════════════════════════════════════ */
:root{
  --readable:#c2cadc;
  --readable-strong:#f1f4fb;
  --readable-muted:#aab4cc;
}

/* Textos auxiliares: usar fonte proporcional e peso médio */
.poup-scenarios-subtitle,
.poup-card-subtitle,
.poup-rule-period,
.poup-scenario-note,
.macro-sub,
.macro-note,
.market-table-title small,
.rank-card-sub,
.docs-note,
.fund-quick-note-disclaimer,
.indic-footnote,
.modal-footer,
.chart-card-sub,
.dolar-chart-sub,
.dolar-day-sub,
.dolar-day-ref,
.dolar-timeline-sub,
.indic-subtitle,
.indic-val-sub,
.indic-pct-label,
.v2-sub,
.ind-v2-sub,
.cdi-ratio-sub,
.copom-item .copom-result,
.mobile-filter-summary,
.mobile-view-toggle-label,
.table-wrap::before,
.indic-table-wrap::before{
  font-family:'Inter',sans-serif !important;
  font-size:clamp(.64rem,1.75vw,.72rem) !important;
  font-weight:500 !important;
  letter-spacing:.005em !important;
  line-height:1.48 !important;
  color:var(--readable-muted) !important;
  text-rendering:optimizeLegibility;
}

/* Labels pequenos em caixa alta: menos espaçamento e melhor contraste */
.filter-label,
.fund-metric-label,
.poup-scenario-pill span,
.focus-explain-kicker,
.fund-quick-note-title,
.docs-title,
.footer-source-label,
.copom-item .copom-num,
.cdi-year-head span,
.cdi-month-chip .m,
.poup-explain-title,
.poup-explain-tag,
.block-divider-label{
  font-family:'Inter',sans-serif !important;
  font-size:.63rem !important;
  font-weight:700 !important;
  letter-spacing:.055em !important;
  line-height:1.28 !important;
  color:var(--readable-muted) !important;
  text-rendering:optimizeLegibility;
}
.block-divider.bloco-atendimento .block-divider-label,
.block-divider.bloco-macro .block-divider-label{
