  letter-spacing:.01em !important;
  text-rendering:optimizeLegibility;
}
.poup-scenario-status{
  font-size:.62rem !important;
  color:#9fc8ff !important;
}
.poup-accum-pill{
  font-size:.66rem !important;
}
.copom-item .copom-date{
