/* ── DÓLAR COMPACTO v3 — resumo executivo ── */
.dolar-compact-section{margin-top:28px}
.dolar-compact-card{
  position:relative;
  overflow:hidden;
  border:1px solid var(--border);
  border-radius:16px;
  background:linear-gradient(180deg,rgba(17,21,38,.92),rgba(12,14,26,.92));
  box-shadow:0 10px 38px rgba(0,0,0,.24);
}
.dolar-compact-card::before{
  content:'';
  display:block;
  height:2px;
  background:linear-gradient(90deg,var(--gold),rgba(46,209,122,.8) 42%,transparent 86%);
}
.dolar-compact-loading{
  padding:22px 24px;
  color:var(--muted);
  font-size:.8rem;
}
.dolar-compact-top{
  display:grid;
  grid-template-columns:250px minmax(0,1fr);
  gap:14px;
  padding:16px 18px 12px;
  align-items:stretch;
}
.dolar-main-kpi{
  border:1px solid rgba(200,151,58,.22);
  border-radius:13px;
  background:rgba(200,151,58,.055);
  padding:15px 16px;
  min-width:0;
}
.dolar-main-kpi .dolar-kpi-label{
  display:block;
  font-size:.58rem;
  text-transform:uppercase;
  letter-spacing:.1em;
  color:var(--muted2);
  font-weight:700;
  margin-bottom:6px;
}
.dolar-main-kpi strong{
  display:block;
  font-family:'Cormorant Garamond',serif;
  font-size:2.25rem;
  line-height:1;
  color:var(--gold2);
  font-weight:700;
  margin-bottom:5px;
}
.dolar-main-kpi small{
  display:block;
  font-family:'JetBrains Mono',monospace;
  font-size:.68rem;
  color:#cbd3e8;
  margin-bottom:0;
}
.dolar-ptax-compact{
  display:inline-flex;
  align-items:center;
  gap:6px;
  max-width:100%;
  padding:5px 8px;
  border-radius:8px;
  border:1px solid rgba(200,151,58,.18);
  background:rgba(200,151,58,.06);
  color:#b6bfd5;
  font-size:.58rem;
  font-family:'JetBrains Mono',monospace;
  white-space:normal;
  line-height:1.35;
}
.dolar-kpi-row{
  display:grid;
  grid-template-columns:repeat(5,minmax(118px,1fr));
  gap:10px;
  align-content:stretch;
}
.dolar-mini-kpi{
  min-width:0;
  padding:14px 15px;
  border-radius:12px;
  border:1px solid var(--border2);
  background:rgba(7,8,15,.46);
}
.dolar-mini-kpi span{
  display:block;
  font-size:.66rem;
  text-transform:uppercase;
  letter-spacing:.08em;
  color:#c4ccdf;
  font-weight:750;
  margin-bottom:8px;
}
.dolar-mini-kpi strong{
  display:block;
  font-family:'Cormorant Garamond',serif;
  font-size:1.48rem;
  line-height:1;
  font-weight:700;
}
.dolar-mini-kpi small{
  display:block;
  margin-top:5px;
  font-size:.60rem;
  color:#8a95b2;
  font-family:'JetBrains Mono',monospace;
}
.dolar-mini-kpi .pos{color:var(--green)}
.dolar-mini-kpi .neg{color:var(--red)}
.dolar-mini-kpi .muted{color:var(--muted)}
.dolar-compact-chart{
  border-top:1px solid var(--border2);
  border-bottom:1px solid var(--border2);
  background:rgba(7,8,15,.22);
}
.dolar-compact-chart-header{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  flex-wrap:wrap;
  padding:13px 18px 10px;
}
.dolar-chart-title{font-family:'Cormorant Garamond',serif;font-size:1rem;font-weight:700;color:var(--gold2)}
.dolar-chart-sub{font-size:.72rem;color:#b8c0d6;font-family:'JetBrains Mono',monospace;margin-top:3px}
.dolar-compact-card .dolar-chart-body{
  height:clamp(210px,22vw,255px);
