/* ── Selic: resumo fora do gráfico para evitar sobreposição no mobile ── */
.selic-summary-row{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:8px;
  padding:10px 16px 0;
}
.selic-summary-chip{
  display:flex;
  align-items:center;
  gap:8px;
  min-width:0;
  padding:9px 10px;
  border-radius:11px;
  border:1px solid var(--border2);
  background:rgba(17,21,38,.72);
}
.selic-summary-chip.max{border-color:rgba(232,187,106,.36);background:rgba(200,151,58,.075)}
.selic-summary-chip.min{border-color:rgba(91,156,246,.34);background:rgba(91,156,246,.07)}
.selic-summary-chip.now{border-color:rgba(46,209,122,.32);background:rgba(46,209,122,.065)}
.selic-summary-dot{
  width:9px;
  height:9px;
  border-radius:50%;
  flex:0 0 9px;
  box-shadow:0 0 12px currentColor;
}
.selic-summary-chip.max .selic-summary-dot{background:var(--gold2);color:var(--gold2)}
.selic-summary-chip.min .selic-summary-dot{background:var(--blue);color:var(--blue)}
.selic-summary-chip.now .selic-summary-dot{background:var(--green);color:var(--green)}
.selic-summary-text{min-width:0;line-height:1.15}
.selic-summary-label{
  display:block;
  color:#a6b0c9;              /* mais claro que muted2 */
  font-size:.58rem;
  letter-spacing:.08em;
  text-transform:uppercase;
  font-weight:700;
  white-space:nowrap;
}
.selic-summary-value{
  display:block;
  margin-top:4px;
  font-family:'Cormorant Garamond',serif;  /* serif para hierarquia */
  font-size:1.05rem;          /* era .70rem — muito pequeno */
  font-weight:700;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  line-height:1;
}
/* Cada chip usa a cor do seu acento */
.selic-summary-chip.max .selic-summary-value{ color:var(--gold2) }
.selic-summary-chip.min .selic-summary-value{ color:#7eb8ff }
.selic-summary-chip.now .selic-summary-value{ color:#4de896 }
.selic-summary-date{
  display:block;
  margin-top:3px;
  color:#8a95b2;              /* levemente mais claro */
  font-family:'JetBrains Mono',monospace;
  font-size:.58rem;           /* era .54rem */
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
@media(max-width:768px){
  .selic-summary-row{
    grid-template-columns:1fr 1fr 1fr;
    gap:6px;
    padding:9px 12px 0;
  }
  .selic-summary-chip{
    flex-direction:column;
    align-items:flex-start;
    gap:5px;
    padding:8px 8px;
  }
  .selic-summary-label{font-size:.50rem}
  .selic-summary-value{font-size:.62rem}
  .selic-summary-date{font-size:.48rem}
  .chart-card .chart-body{padding-top:12px}
}
@media(max-width:430px){
  .selic-summary-row{grid-template-columns:repeat(3,minmax(92px,1fr));overflow-x:auto;-webkit-overflow-scrolling:touch;padding-bottom:2px}
  .selic-summary-row::-webkit-scrollbar{display:none}
  .selic-summary-chip{min-width:92px}
}


/* ── Patch inline 1 (extraído do HTML) ── */
/* ══ BARRA GLOBAL ══ */
#gfb{
  position:fixed;top:0;left:0;right:0;z-index:150;
  background:rgba(7,8,15,.96);
  border-bottom:1px solid rgba(200,151,58,.28);
  box-shadow:0 4px 28px rgba(0,0,0,.55);
  backdrop-filter:blur(12px);
  -webkit-backdrop-filter:blur(12px);
}
#gfb-inner{
  max-width:1760px;margin:0 auto;
  display:flex;align-items:center;gap:10px;
  padding:7px 24px;
  height:52px;
}
#gfb-logo{
  font-size:1.1rem;flex-shrink:0;opacity:.9;
  display:none; /* só desktop largo */
}
#gfb-search-wrap{
  position:relative;flex:0 0 260px;
}
#gfb-icon{
  position:absolute;left:10px;top:50%;transform:translateY(-50%);
  color:var(--muted2);pointer-events:none;
}
#gfbSearch{
  width:100%;padding:7px 28px 7px 32px;
  background:rgba(255,255,255,.06);
  border:1px solid rgba(200,151,58,.22);
  border-radius:10px;
  color:var(--text);
  font-family:'Inter',sans-serif;
  font-size:.8rem;
  outline:none;
  transition:border-color .2s,box-shadow .2s;
  -webkit-appearance:none;
}
#gfbSearch:focus{border-color:var(--gold);box-shadow:0 0 0 3px rgba(200,151,58,.18)}
#gfbSearch::placeholder{color:var(--muted2)}
#gfbClear{
  position:absolute;right:8px;top:50%;transform:translateY(-50%);
  background:transparent;border:none;color:var(--muted2);cursor:pointer;
  font-size:.75rem;padding:2px 4px;border-radius:4px;
  display:none;transition:color .15s;
}
#gfbClear.visible{display:block}
#gfbClear:hover{color:var(--text)}

/* Chips de categoria */
#gfb-chips{
  display:flex;gap:5px;flex:1;overflow-x:auto;
  scrollbar-width:none;-webkit-overflow-scrolling:touch;
  padding:2px 0;
}
#gfb-chips::-webkit-scrollbar{display:none}
.gfb-chip{
  flex-shrink:0;
  padding:4px 11px;
  border-radius:20px;
  border:1px solid rgba(255,255,255,.1);
  background:transparent;
  color:#9aa6c3;
  font-family:'Inter',sans-serif;
  font-size:.72rem;
  font-weight:500;
  cursor:pointer;
  transition:all .15s;
  white-space:nowrap;
}
.gfb-chip:hover{border-color:rgba(200,151,58,.5);color:var(--gold2)}
.gfb-chip-active{
  background:rgba(200,151,58,.15);
  border-color:var(--gold);
  color:var(--gold2);
  font-weight:700;
}

/* Direita: count + botão */
#gfb-right{
  display:flex;align-items:center;gap:8px;flex-shrink:0;margin-left:auto;
}
#gfbCount{
  font-family:'JetBrains Mono',monospace;
  font-size:.7rem;color:var(--muted);
  white-space:nowrap;
}
#gfbCount strong{color:var(--gold2);font-size:.78rem}
#gfbGo{
  padding:5px 13px;
  background:linear-gradient(135deg,rgba(200,151,58,.2),rgba(200,151,58,.1));
  border:1px solid rgba(200,151,58,.4);
  border-radius:8px;
  color:var(--gold2);
  font-family:'Inter',sans-serif;
  font-size:.72rem;
  font-weight:700;
  cursor:pointer;
  transition:all .15s;
  white-space:nowrap;
}
#gfbGo:hover{background:rgba(200,151,58,.25);border-color:var(--gold2)}

/* Empurra o conteúdo da página pra baixo */
body{padding-top:52px !important}

/* Ajuste do z-index do header original */
header{position:relative;z-index:1}

/* ── MOBILE ── */
@media(max-width:768px){
  #gfb-inner{padding:6px 12px;gap:7px;height:48px}
  #gfb-search-wrap{flex:1;min-width:0}
  #gfbSearch{font-size:.76rem;padding:6px 26px 6px 28px}
  #gfb-chips{display:none} /* filtros apenas na seção abaixo */
  #gfbCount{font-size:.65rem}
  #gfbGo{padding:5px 10px;font-size:.66rem}
  body{padding-top:48px !important}
}
@media(min-width:1200px){
  #gfb-logo{display:flex}
  #gfb-search-wrap{flex:0 0 300px}
}

/* ══ FAV BOTÃO — TABELA ══ */
.fav-btn{background:transparent;border:none;cursor:pointer;font-size:.85rem;line-height:1;padding:2px 4px;border-radius:4px;opacity:.3;transition:opacity .15s,transform .15s;vertical-align:middle}
.fav-btn:hover{opacity:.7;transform:scale(1.15)}
.fav-btn.is-fav{opacity:1;filter:drop-shadow(0 0 4px #e8bb6a)}
tbody tr.row-fav{background:rgba(200,151,58,.045)!important;border-left:2px solid var(--gold)!important}
tbody tr.row-fav:hover{background:rgba(200,151,58,.08)!important}

/* ══ FAV BOTÃO — CARD MOBILE ══ */
.fund-card-mobile-head{position:relative}
.fav-btn-mobile{position:absolute;top:10px;right:10px;background:rgba(7,8,15,.55);border:1px solid rgba(200,151,58,.22);border-radius:8px;width:32px;height:32px;display:flex;align-items:center;justify-content:center;font-size:1rem;cursor:pointer;opacity:.5;transition:opacity .15s;-webkit-tap-highlight-color:transparent}
.fav-btn-mobile:active{transform:scale(.9)}
.fav-btn-mobile.is-fav{opacity:1;background:rgba(200,151,58,.14);border-color:rgba(200,151,58,.5)}
.fund-card-mobile.card-fav{border-color:rgba(200,151,58,.42)!important;background:linear-gradient(180deg,rgba(200,151,58,.07),rgba(17,21,38,.94))!important}

/* ══ CHIP FAVORITOS ══ */
.chip.fav-chip{border-color:rgba(200,151,58,.35);color:var(--gold2)}
.chip.fav-chip.active{background:var(--gold-dim);border-color:var(--gold);color:var(--gold2)}
