/* ── Fund Spotlight Modal ── */

/* ═══════════════════════════════════════════
   FUND SPOTLIGHT MODAL
   Desktop: card centralizado flutuante
   Mobile:  bottom sheet deslizante
═══════════════════════════════════════════ */
.fspot-overlay{
  position:fixed;inset:0;z-index:2000;
  background:rgba(0,0,0,0);
  pointer-events:none;
  transition:background .25s;
}
.fspot-overlay.open{
  background:rgba(0,0,0,.62);
  pointer-events:all;
  backdrop-filter:blur(3px);
}

/* ── Painel desktop (modal centralizado) ── */
.fspot-panel{
  position:absolute;
  top:50%;left:50%;
  transform:translate(-50%, calc(-50% + 24px));
  opacity:0;
  width:min(620px, 94vw);
  max-height:88vh;
  overflow-y:auto;
  background:var(--bg2);
  border:1px solid var(--border);
  border-radius:20px;
  padding:0 0 20px;
  box-shadow:0 32px 80px rgba(0,0,0,.55);
  transition:transform .28s cubic-bezier(.34,1.42,.64,1), opacity .22s;
  pointer-events:none;
}
.fspot-overlay.open .fspot-panel{
  transform:translate(-50%,-50%);
  opacity:1;
  pointer-events:all;
}

/* Handle mobile (escondido no desktop) */
.fspot-handle{ display:none }

/* ── Mobile: bottom sheet ── */
@media(max-width:768px){
  .fspot-panel{
    top:auto;left:0;right:0;bottom:0;
    transform:translateY(100%);
    width:100%;
    max-height:92dvh;
    border-radius:20px 20px 0 0;
    border-bottom:none;
  }
  .fspot-overlay.open .fspot-panel{
    transform:translateY(0);
  }
  .fspot-handle{
    display:block;
    width:40px;height:4px;
    background:rgba(255,255,255,.2);
    border-radius:2px;
    margin:12px auto 0;
  }
}

/* ── Header ── */
.fspot-header{
  display:flex;align-items:flex-start;justify-content:space-between;
  gap:12px;padding:20px 22px 14px;
  border-bottom:1px solid var(--border2);
}
.fspot-header-left{ display:flex;align-items:flex-start;gap:10px;min-width:0 }
.fspot-badge{
  flex-shrink:0;padding:3px 10px;border-radius:6px;
  font-size:.6rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  margin-top:3px;
}
.fspot-badge.best{
  background:rgba(46,209,122,.12);color:var(--green);border:1px solid rgba(46,209,122,.25);
}
.fspot-badge.worst{
  background:rgba(240,85,101,.12);color:var(--red);border:1px solid rgba(240,85,101,.22);
}
.fspot-title{
  font-family:'Cormorant Garamond',serif;
  font-size:1.15rem;font-weight:700;color:var(--text);line-height:1.3;
}
.fspot-meta{
  font-size:.65rem;color:var(--muted);margin-top:3px;
  font-family:'JetBrains Mono',monospace;
}
.fspot-close{
  flex-shrink:0;background:var(--bg3);border:1px solid var(--border2);
  color:var(--muted);border-radius:8px;padding:5px 9px;
  font-size:.9rem;cursor:pointer;line-height:1;
  transition:all .15s;
}
.fspot-close:hover{ background:var(--red-dim);color:var(--red);border-color:var(--red) }

/* ── Métricas ── */
.fspot-metrics{
  display:grid;grid-template-columns:repeat(4,1fr);
  gap:10px;padding:16px 22px;
  border-bottom:1px solid var(--border2);
}
@media(max-width:480px){
  .fspot-metrics{ grid-template-columns:repeat(2,1fr) }
}
.fspot-metric-item{
  display:flex;flex-direction:column;gap:3px;
  padding:10px 12px;border-radius:10px;
  background:var(--bg3);border:1px solid var(--border2);
}
.fspot-metric-label{
  font-size:.58rem;text-transform:uppercase;letter-spacing:.1em;
  color:var(--muted2);font-weight:600;
}
.fspot-metric-val{
  font-family:'Cormorant Garamond',serif;
  font-size:1.35rem;font-weight:700;line-height:1;
}
.fspot-metric-val.pos{ color:var(--green) }
.fspot-metric-val.neg{ color:var(--red) }
.fspot-metric-val.neu{ color:var(--gold2) }
.fspot-metric-sub{
  font-size:.58rem;color:var(--muted2);
  font-family:'JetBrains Mono',monospace;
}

/* ── Liquidez ── */
.fspot-liq{
  display:flex;align-items:center;gap:8px;
  padding:10px 22px;
  border-bottom:1px solid var(--border2);
  flex-wrap:wrap;
}
.fspot-liq-label{
  font-size:.6rem;text-transform:uppercase;letter-spacing:.1em;
  color:var(--muted2);font-weight:600;min-width:54px;
}
.fspot-liq-badge{
  display:inline-flex;align-items:center;gap:5px;
  padding:4px 10px;border-radius:6px;font-size:.68rem;font-weight:600;
  font-family:'JetBrains Mono',monospace;
  background:#2a1f08;color:#e8b84b;border:1px solid #4a3510;
}

/* ── Nota rápida ── */
.fspot-note{
  margin:12px 22px;padding:12px 14px;
  border-radius:10px;border:1px solid var(--border2);
  background:rgba(91,156,246,.04);
  font-size:.72rem;color:var(--muted);line-height:1.6;
}
.fspot-note-title{
  font-size:.58rem;text-transform:uppercase;letter-spacing:.1em;
  color:var(--gold);font-weight:700;margin-bottom:5px;
}

/* ── Ações ── */
.fspot-actions{
  display:flex;gap:8px;padding:4px 22px 10px;flex-wrap:wrap;
}
.fspot-btn-primary{
  flex:1;padding:9px 14px;border-radius:10px;
  background:var(--gold-dim);border:1px solid var(--gold);
  color:var(--gold2);font-family:'Inter',sans-serif;
  font-size:.78rem;font-weight:700;cursor:pointer;
  transition:all .15s;
}
.fspot-btn-primary:hover{ background:rgba(200,151,58,.2);color:var(--gold3) }
.fspot-btn-secondary{
  padding:9px 14px;border-radius:10px;
  background:var(--bg3);border:1px solid var(--border2);
  color:var(--muted);font-family:'Inter',sans-serif;
  font-size:.78rem;font-weight:600;cursor:pointer;text-decoration:none;
  transition:all .15s;display:inline-flex;align-items:center;
}
.fspot-btn-secondary:hover{ border-color:var(--blue);color:var(--blue) }

/* ── Documentos ── */
.fspot-docs{
  display:flex;gap:6px;flex-wrap:wrap;padding:6px 22px 0;
}
.fspot-doc-btn{
  padding:5px 10px;border-radius:7px;
  background:var(--bg3);border:1px solid var(--border2);
  color:var(--muted);font-size:.65rem;font-family:'Inter',sans-serif;font-weight:600;
  text-decoration:none;cursor:pointer;transition:all .15s;
}
.fspot-doc-btn:hover{ border-color:var(--gold);color:var(--gold2);background:var(--gold-dim) }

/* ── Centralização colunas numéricas (pct, 12M, CDI) ── */
th.th-num, td.col-pct, td.col-pct-12m, td.col-cdi-bar, td.cdi-ratio-cell{
  text-align:center !important;
}

/* ── Separadores de grupo coloridos por categoria ── */
.group-row .group-lbl-line{height:1px;background:var(--border)}
/* linha dourada para taxas de referência (primeiro grupo) */
.indic-table-v2 tbody tr.group-row:nth-of-type(1) td{border-top-color:rgba(200,151,58,.45)}
/* linha azul para câmbio */
.indic-table-v2 tbody tr.group-row:nth-of-type(2) td{border-top-color:rgba(91,156,246,.4)}
/* linha verde para bolsa brasil */
.indic-table-v2 tbody tr.group-row:nth-of-type(3) td{border-top-color:rgba(46,209,122,.35)}
/* linha roxa para bolsa EUA */
.indic-table-v2 tbody tr.group-row:nth-of-type(4) td{border-top-color:rgba(167,139,250,.35)}

/* ── Coluna Acum. 12M — destaque sutil como coluna-foco ── */
.indic-table-v2 th.th-acum{
  background:rgba(200,151,58,.06);
  border-left:1px solid rgba(200,151,58,.18);
  border-right:1px solid rgba(200,151,58,.18);
}
.indic-table-v2 td:last-child{
  background:rgba(200,151,58,.03);
  border-left:1px solid rgba(200,151,58,.1);
  border-right:1px solid rgba(200,151,58,.1);
}


