  transition:opacity .2s ease;
  z-index:9990;
}
.closed-market-sheet{
  position:fixed;
  left:50%;
  bottom:0;
  transform:translate(-50%, 110%);
  width:min(720px, calc(100vw - 24px));
  max-height:min(82vh, 780px);
  overflow:auto;
  border:1px solid rgba(231,185,95,.32);
  border-radius:28px 28px 0 0;
