  box-shadow:0 -24px 70px rgba(0,0,0,.48);
  z-index:9991;
  padding:12px 18px calc(20px + env(safe-area-inset-bottom));
  transition:transform .25s ease, opacity .2s ease;
  opacity:0;
}

