/* ════════════════════════════════════════════════════════════════════
   PATCHES CSS — todas as melhorias das sessões anteriores
════════════════════════════════════════════════════════════════════ */

/* ── Tokens de cor unificados ────────────────────────────────────── */
:root{
  --color-up:       #2ed17a;
  --color-down:     #f05565;
  --color-neutral:  #b4bdd3;
  --color-up-dim:   rgba(46,209,122,.13);
  --color-down-dim: rgba(240,85,101,.11);
  --text-xs:   .68rem;
  --text-sm:   .75rem;
  --text-base: .875rem;
  --text-md:   1rem;
  --text-lg:   1.125rem;
  --text-xl:   1.25rem;
  --text-2xl:  1.5rem;
  --text-3xl:  2rem;
}

/* ── Exec Bar ───────────────────────────────────────────────────── */
.exec-bar{
  position:sticky;top:0;z-index:800;
  background:rgba(7,8,15,.96);
  backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);
  border-bottom:1px solid rgba(200,151,58,.18);
  padding:0 16px;
}
.exec-bar-inner{
  display:flex;align-items:center;gap:0;
  max-width:1400px;margin:0 auto;height:38px;
  overflow-x:auto;scrollbar-width:none;
}
.exec-bar-inner::-webkit-scrollbar{display:none}
.exec-item{display:flex;align-items:center;gap:7px;padding:0 14px;white-space:nowrap;cursor:help;flex-shrink:0}
.exec-sep{width:1px;height:18px;background:rgba(180,189,211,.18);flex-shrink:0}
.exec-label{font-family:'Inter',sans-serif;font-size:.62rem;font-weight:600;text-transform:uppercase;letter-spacing:.07em;color:var(--muted)}
.exec-val{font-family:'JetBrains Mono',monospace;font-size:.82rem;font-weight:700;color:var(--text)}
.exec-val.pos{color:var(--color-up)}.exec-val.neg{color:var(--color-down)}.exec-val.neu{color:var(--color-neutral)}

/* ── Seções colapsáveis ─────────────────────────────────────────── */
/* ── Seções colapsáveis — UX redesign: borda visível + hover dourado ── */
.section-title-collapsible{
  cursor:pointer;
  user-select:none;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  border:1px solid rgba(180,189,211,.16);
  border-radius:14px;
  padding:12px 16px;
  margin:0;
  background:rgba(13,15,28,1);
  transition:border-color .2s ease, background .2s ease;
}
.section-title-collapsible:hover{
  border-color:rgba(200,151,58,.35);
  background:rgba(200,151,58,.07);
}
.section-title-collapsible:focus-visible{
  outline:2px solid var(--gold);
  outline-offset:2px;
  border-radius:14px;
}
/* Estado expandido */
.section-expanded>.section-title-collapsible,
.collapsible-section.section-expanded>.section-title-collapsible{
  border-color:rgba(200,151,58,.35);
  background:rgba(200,151,58,.07);
  border-bottom-left-radius:0;
  border-bottom-right-radius:0;
}
/* Botão toggle — agora dourado e visível */
.section-toggle-btn{
  display:flex;
  align-items:center;
