  body.closed-market-open #closedMarketSheet,
  body.closed-market-open .closed-market-sheet,
  #closedMarketSheet[aria-hidden="false"]{
    transform:translate(-50%, -50%)!important;
    opacity:1!important;
    visibility:visible!important;
    pointer-events:auto!important;
  }
}



