/* ════════════════════════════════════════════════════
   PATCH v124 — Design System Tokens + legibilidade
   Objetivo:
   - Criar tokens globais sem refatorar o projeto inteiro.
   - Melhorar legibilidade e padronização visual dos blocos mais relevantes.
   - Evitar regressão nos patches estáveis v108/v118/v119/v120/v121/v122/v123.
════════════════════════════════════════════════════ */

/* 1) Tokens globais: camada superior de Design System */
:root{
  /* Cores principais */
  --ds-text-primary:#f4f7ff;
  --ds-text-secondary:#a6b0c9;
  --ds-text-muted:#7f8aa7;
  --ds-text-soft:#cbd5ee;

  --ds-bg-page:#050610;
  --ds-bg-card:#0d0f1c;
  --ds-bg-card-soft:#111426;
  --ds-bg-panel:rgba(14,17,31,.82);
  --ds-bg-panel-strong:rgba(18,22,38,.92);

  --ds-border-soft:rgba(255,255,255,.08);
  --ds-border-medium:rgba(255,255,255,.12);
  --ds-border-gold:rgba(232,187,106,.34);
  --ds-border-blue:rgba(91,141,218,.24);

  --ds-accent:#e8bb6a;
  --ds-accent-strong:#f0c878;
  --ds-positive:#2ed17a;
  --ds-negative:#ff5c7a;
  --ds-warning:#f2c46f;
  --ds-blue:#7ba7ff;

  /* Tipografia */
  --ds-font-ui:'Inter',system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  --ds-font-data:'JetBrains Mono','SFMono-Regular',Consolas,monospace;
  --ds-font-display:'Cormorant Garamond',Georgia,serif;

  --ds-font-2xs:.56rem;
  --ds-font-xs:.62rem;
  --ds-font-sm:.72rem;
  --ds-font-md:.88rem;
  --ds-font-lg:1.08rem;
  --ds-font-xl:1.28rem;
  --ds-font-2xl:1.55rem;

  --ds-line-tight:1.08;
  --ds-line-title:1.16;
  --ds-line-body:1.38;

  /* Espaçamentos */
  --ds-gap-2xs:4px;
  --ds-gap-xs:6px;
  --ds-gap-sm:10px;
  --ds-gap-md:14px;
  --ds-gap-lg:18px;
  --ds-gap-xl:24px;

  /* Bordas e sombras */
  --ds-radius-sm:10px;
  --ds-radius-md:14px;
  --ds-radius-lg:18px;
  --ds-radius-card:22px;
  --ds-radius-pill:999px;

  --ds-shadow-card:0 18px 42px rgba(0,0,0,.24);
  --ds-shadow-inner:inset 0 1px 0 rgba(255,255,255,.045);
}

/* 2) Aplicação segura nos blocos de maior impacto visual */
.site-header-clean,
.executive-summary,
.fund-filter-shell,
.market-ref-card,
.indic-ref-card,
.closed-month-launch,
.ranking-card,
.ranking-panel,
.focus-card{
  color:var(--ds-text-primary);
}

/* Títulos principais e seções */
.site-header-clean .brand-text h1,
.section-title h2,
.market-title-left h2,
.ranking-title-group h2,
.focus-title-line h2,
.market-table-title span{
  font-family:var(--ds-font-ui)!important;
