  font-weight:850!important;
  line-height:var(--ds-line-title)!important;
  letter-spacing:-.012em!important;
}

/* Subtítulos */
.site-header-clean .brand-text p,
.section-title p,
.market-table-title small,
.closed-month-launch-copy small,
.cdi-rel,
.indic-ref-sub,
.fcad-sub{
