  color:var(--ds-text-secondary)!important;
  font-weight:800!important;
  letter-spacing:.075em!important;
  text-transform:uppercase!important;
}

/* Valores de destaque */
.kpi-value,
.indic-ref-val,
.macro-main-value,
.closed-card-value,
.market-big-value{
  font-family:var(--ds-font-display)!important;
